/* Approved Atalanta comparator: warm paper, gold and sky-blue data bars. */
body :is(#app,#team-squad-app) .comparator-editorial{padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none;color:#243a3b;font-family:var(--ds-font-body)}
body :is(#app,#team-squad-app) .team-comparator-toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:28px}
body :is(#app,#team-squad-app) .team-comparator-toolbar h2{position:relative;margin:0;padding-top:16px;font:700 24px/1.25 var(--ds-font-body);letter-spacing:-.025em;color:#243a3b}
body :is(#app,#team-squad-app) .team-comparator-toolbar h2::before{content:"";position:absolute;left:0;top:0;width:48px;height:3px;background:var(--gold)}
body :is(#app,#team-squad-app) .team-comparator-options{display:flex;flex-wrap:wrap;align-items:center;gap:12px}
body :is(#app,#team-squad-app) .team-comparator-options :is(.comparison-mode,.team-period-control){display:block;min-width:0;max-width:100%;margin:0}
body :is(#app,#team-squad-app) .comparator-editorial :is(input,select){background:#fff!important;color:#243a3b!important;border:1px solid #cfd7db!important;border-radius:7px!important;box-shadow:none;color-scheme:light;font-family:var(--ds-font-body)}
body :is(#app,#team-squad-app) .team-comparator-options select{height:40px;width:auto;max-width:100%;padding:8px 32px 8px 12px;font-size:12px}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-controls:empty{display:none}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head{display:grid;grid-template-columns:minmax(0,1fr) 100px minmax(0,1fr);align-items:stretch;gap:24px;margin:0 0 28px}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head article{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:1fr auto;gap:16px;min-width:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none;text-align:left}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head article:last-child .player-comparison-details{text-align:right}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details h3{margin:0 0 7px;font:700 clamp(17px,1.7vw,21px)/1.25 var(--ds-font-body);letter-spacing:-.025em;overflow-wrap:anywhere;color:#243a3b}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details p{margin:0 0 7px;font:400 14px/1.5 var(--ds-font-body);color:#43595b}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details strong{font:400 14px/1.5 var(--ds-font-body);color:#243a3b}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs{display:flex;align-items:center;gap:12px;align-self:start;margin-top:32px;color:var(--gold);font:700 14px/1 var(--ds-font-body)}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::before,body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::after{content:"";height:1px;background:var(--gold);flex:1}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head article>label{grid-column:1/-1;margin:0;text-align:left}
body :is(#app,#team-squad-app) .comparator-editorial label{color:#43595b;font:400 12px/1.5 var(--ds-font-body);letter-spacing:0;text-transform:none;min-width:0}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head article>label{font-size:0}
body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete{position:relative;display:block;min-width:0;max-width:100%;padding:0}
body :is(#app,#team-squad-app) .comparator-editorial input{width:100%;max-width:100%;min-width:0;height:44px;box-sizing:border-box;padding:10px 36px 10px 14px;font:400 13px/1.4 var(--ds-font-body)}
body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::after{content:"";position:absolute;right:15px;top:14px;width:11px;height:11px;border:1.5px solid #43595b;border-radius:50%;pointer-events:none;background:linear-gradient(#43595b,#43595b) no-repeat 10px 10px/5px 2px}
body :is(#app,#team-squad-app) .comparator-editorial article:focus-within{position:relative;z-index:25}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions{position:absolute;display:block;top:52px;left:0;right:0;width:100%;box-sizing:border-box;margin:0;max-height:240px;overflow-y:auto;overscroll-behavior:contain;background:#fff;color:#243a3b;z-index:30}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions[hidden]{display:none}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button:is(:hover,:focus-visible,.active){background:#d9f1fa;color:#163c4e}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button:is(:hover,:focus-visible,.active) small{color:#36596a}
body :is(#app,#team-squad-app) .comparator-editorial:has(.player-comparator-result:empty){padding-bottom:264px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-bars{border:1px solid #d6dcde;border-radius:9px;background:rgba(255,255,255,.65);padding:0;overflow:hidden}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-row{display:grid;grid-template-columns:80px minmax(0,1fr) 180px minmax(0,1fr) 80px;align-items:center;gap:24px;min-height:54px;box-sizing:border-box;padding:12px 20px;margin:0;border-bottom:1px solid #e0e5e6;background:transparent;color:#243a3b;font:400 13px/1.5 var(--ds-font-body);font-variant-numeric:tabular-nums}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-row:last-child{border-bottom:0}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-row>strong{font:700 17px/1.4 var(--ds-font-body);text-align:center;color:#243a3b}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-label{text-align:center;color:#243a3b;font:500 13px/1.4 var(--ds-font-body)}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-track{display:flex;height:8px;border-radius:8px;background:#edf0f0;overflow:hidden}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-track.left{justify-content:flex-end}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-track i{height:100%;border-radius:inherit;background:linear-gradient(90deg,#b69857,#c7b27d)}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-track.right i{background:linear-gradient(90deg,#9ed5e7,#b8e3f0)}
@media(max-width:700px){
 body :is(#app,#team-squad-app) .team-comparator-toolbar{flex-wrap:wrap;gap:16px;margin-bottom:24px}
 body :is(#app,#team-squad-app) .team-comparator-toolbar h2{font-size:20px}
 body :is(#app,#team-squad-app) .team-comparator-options{gap:8px}
 body :is(#app,#team-squad-app) .team-comparator-options select{font-size:11px;padding-left:8px;padding-right:24px}
 body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head{grid-template-columns:minmax(0,1fr) 26px minmax(0,1fr);gap:8px;margin-bottom:20px}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs{font-size:11px;gap:0;margin-top:24px;justify-content:center}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::before,body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::after{display:none}
 body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details h3{font-size:17px}
 body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details :is(p,strong){font-size:11px}
 body :is(#app,#team-squad-app) .comparator-editorial input{font-size:11px;padding:8px 24px 8px 8px;height:40px}
 body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::after{right:9px;top:13px;width:9px;height:9px}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-row{grid-template-columns:26px minmax(0,1fr) 94px minmax(0,1fr) 26px;gap:6px;padding:12px 8px;min-height:52px}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-row>strong{font-size:13px}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-label{font-size:11px}
 body :is(#app,#team-squad-app) .comparator-editorial .comparison-track{height:6px}
}

body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details h3{font-weight:700!important}
body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::before{content:"";position:absolute;right:12px;top:26px;width:6px;height:1.5px;background:#43595b;transform:rotate(45deg);pointer-events:none}
@media(max-width:700px){
 body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::before{right:6px;top:23px;width:5px}
}

body :is(#app,#team-squad-app) .team-comparator-toolbar h2{padding-top:0;font-family:var(--ds-font-display);font-size:var(--ds-title-section);font-weight:400!important;line-height:1.18;letter-spacing:.025em}
body :is(#app,#team-squad-app) .team-comparator-toolbar h2::before{content:none}

body :is(#app,#team-squad-app) .comparator-editorial input{color:#000!important;-webkit-text-fill-color:#000}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button strong,
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button:is(:hover,:focus-visible,.active) strong{color:#000;-webkit-text-fill-color:#000}

body :is(#app,#team-squad-app) .comparator-editorial .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
body :is(#app,#team-squad-app) .comparator-editorial .team-comparator-toolbar{width:100%;box-sizing:border-box}
body :is(#app,#team-squad-app) .comparator-editorial .team-comparator-toolbar h2{flex:1 1 auto}
