body,button,input,select,textarea{font-family:var(--font-body)}

.round16-info-box{position:relative;min-height:190px;padding:22px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.86),rgba(255,255,255,.58));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.round16-info-box>span{position:absolute;right:18px;top:16px;color:rgba(167,116,22,.32);font-size:32px;font-weight:900}

.round16-info-box h2{padding-right:38px;font-size:24px}

.round16-info-box>p{max-width:80%}

.round16-info-box>small{display:block;margin-top:12px;color:var(--muted)}

.round16-formations{min-width:0}

.round16-formations>small a{font-weight:800}

.pitch-centre-line,.pitch-centre-circle,.pitch-box{position:absolute;z-index:-1;pointer-events:none}

.pitch-centre-line{top:50%;left:0;width:100%;border-top:1px solid rgba(255,255,255,.7)}

.pitch-centre-circle{top:50%;left:50%;width:180px;height:180px;border:1px solid rgba(255,255,255,.7);border-radius:50%;transform:translate(-50%,-50%)}

.pitch-centre-circle::after{content:"";position:absolute;top:50%;left:50%;width:6px;height:6px;border-radius:50%;background:#fff;transform:translate(-50%,-50%)}

.pitch-box{left:50%;width:44%;height:110px;border:1px solid rgba(255,255,255,.72);transform:translateX(-50%)}

.pitch-box-top{top:-1px;border-top:0}

.pitch-box-bottom{bottom:-1px;border-bottom:0}

.round16-formations>small{display:block;line-height:1.45}

.source-check{display:inline-flex;max-width:165px;padding:5px 8px;border-radius:8px;background:rgba(255,255,255,.06);color:var(--muted);font-size:10px;font-weight:800}

.source-check.is-exact{background:rgba(39,209,127,.1);color:#65e7a4}

.source-check.is-different{background:rgba(242,193,78,.1);color:#ffe39a}

.global-stat-group{grid-template-columns:92px minmax(0,1fr);align-items:center;gap:12px}

.global-stat-group>strong{padding:0;letter-spacing:.09em}

.global-stat-group>div{gap:7px}

.global-stat-button{min-height:32px;padding:6px 11px;box-shadow:inset 0 1px rgba(255,255,255,.72)}

.global-stat-button.active{box-shadow:0 5px 12px rgba(167,116,22,.16),inset 0 1px rgba(255,255,255,.7)}

/* Recent results: letters keep outcomes readable without relying on colour. */
.standings-form{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.standings-form-result{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;font:600 12px/1 var(--ds-font-body);color:#fff;background:#526174}
.standings-form-result.is-win{background:#087f6c;color:#fff}
.standings-form-result.is-draw{background:#e0e4e9;color:#233144}
.standings-form-result.is-loss{background:#c83e49;color:#fff}
.standings-form-empty{color:var(--ds-color-text-muted);font-size:12px}

/* Keep recent form beside the final disciplinary column. */
body[data-page="home"] .home-standings .standings-table :is(th,td):last-child,
body[data-page="champions"] .champions-overview .champions-standings-table :is(th,td):last-child{box-sizing:border-box;width:116px;min-width:116px;padding-left:6px;padding-right:12px;text-align:left;white-space:nowrap}
body[data-page="home"] .home-standings .standings-table :is(th,td):nth-last-child(2),
body[data-page="champions"] .champions-overview .champions-standings-table :is(th,td):nth-last-child(2){box-sizing:border-box;width:48px;padding-left:6px;padding-right:6px;text-align:center}

/* Align recent results and heading on the same centred column. */
body[data-page="home"] .home-standings .standings-table :is(th,td):last-child{width:182px;min-width:182px;padding-inline:10px;text-align:center}
body[data-page="champions"] .champions-overview .champions-standings-table :is(th,td):last-child{width:182px;min-width:182px;padding-inline:10px;text-align:center}
body[data-page="home"] .home-standings .standings-table :is(th,td):nth-last-child(2),
body[data-page="champions"] .champions-overview .champions-standings-table :is(th,td):nth-last-child(2){width:56px;padding-inline:8px}
.standings-form{vertical-align:middle;justify-content:center}

/* Compact recent form without sacrificing the five-result history. */
.standings-form{gap:4px}
.standings-form-result{width:20px;height:20px;font-size:10px}
body[data-page="home"] .home-standings .standings-table :is(th,td):last-child,
body[data-page="champions"] .champions-overview .champions-standings-table :is(th,td):last-child{width:128px;min-width:128px;padding-inline:6px}

css/home.css:
/* home.css - modulo del sistema grafico condiviso. */
/* Classifiche: selettore stagione, punti prioritari e stemmi. */
.standings-switch{display:flex;gap:10px;margin:24px 0 8px;padding:7px;border:1px solid var(--line);border-radius:14px;background:rgba(8,24,43,.82)}

.standings-switch button{flex:1;padding:11px 16px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--muted);font-weight:800;cursor:pointer}

.standings-switch button:hover,.standings-switch button.active{border-color:rgba(67,119,205,.55);background:rgba(23,79,165,.3);color:#fff}

.standings-table{min-width:800px;table-layout:fixed}

.standings-table th:first-child,.standings-table td:first-child{width:54px}

.standings-table th:nth-child(3),.standings-table td:nth-child(3){text-align:left}

.standings-table th:nth-child(n+4),.standings-table td:nth-child(n+4){width:72px;padding-right:12px;padding-left:12px;text-align:center}

.standings-table th:nth-child(4),.standings-table td:nth-child(4){color:var(--gold)}

/* Small PT header: retain gold identity with readable contrast on the ice surface. */
body[data-page="home"] .home-standings .standings-table thead th:nth-child(4):not(.standings-column-active){color:#805b16}

/* Hero fotografica della Home. */


.hero{position:relative;isolation:isolate;min-height:390px;align-items:center;overflow:hidden;padding:clamp(30px,5vw,58px);border-color:rgba(111,153,218,.42);border-radius:var(--radius-lg);background:linear-gradient(100deg,rgba(3,12,34,.97) 0,rgba(5,18,43,.88) 43%,rgba(8,29,72,.28) 72%),url("../assets/images/optimized/home-hero-1600.webp") center/cover;box-shadow:var(--shadow-lg)}

.hero-season{justify-self:end;align-self:end;display:grid;min-width:190px;padding:22px;border:1px solid rgba(244,203,105,.32);border-radius:22px;background:rgba(2,11,34,.68);backdrop-filter:blur(12px)}

.hero-season>span{color:var(--gold);font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}

.hero-season strong{font-size:55px;line-height:1}

.hero-season strong span{color:var(--gold)}

.hero-season small{margin-top:8px;color:var(--muted)}

.home-dashboard-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(270px,.65fr);gap:18px}

.home-next{padding:22px;border:1px solid var(--line);border-radius:22px;background:rgba(5,22,54,.72)}

.home-next h3{margin:0;color:var(--muted);font-size:12px;letter-spacing:.1em;text-transform:uppercase}

.home-next-head{display:grid;grid-template-columns:minmax(140px,.72fr) minmax(280px,1.55fr);align-items:center;gap:18px;margin-bottom:16px}

.home-matchday-nav{display:flex;grid-column:2;justify-self:center;gap:8px}

.home-matchday-button{padding:9px 13px;border:1px solid rgba(23,79,145,.22);border-radius:999px;background:#174f91;color:#fff;font:800 11px/1 Inter,sans-serif;cursor:pointer;box-shadow:0 5px 14px rgba(23,79,145,.18);transition:transform .18s ease,box-shadow .18s ease,opacity .18s ease}

.home-matchday-button:hover:not(:disabled),.home-matchday-button:focus-visible:not(:disabled){transform:translateY(-1px);box-shadow:0 7px 17px rgba(23,79,145,.26)}

.home-matchday-button:disabled{cursor:default;opacity:.45}

.home-match-score{min-width:42px;color:#173d68;font-size:15px;text-align:center}

.home-match-row.is-finished .home-match-score{font-weight:900}

.home-rail{display:grid;gap:10px}

.home-rail a{display:flex;flex-direction:column;justify-content:center;min-height:126px;padding:18px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(18,54,118,.62),rgba(5,22,54,.82));text-decoration:none;transition:.2s ease}

.home-rail a:hover{border-color:var(--gold);transform:translateX(3px)}

.home-rail span{color:var(--gold);font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}

.home-rail strong{margin:4px 0;font-size:17px}

.home-rail small{color:var(--muted)}

.editorial-empty{display:grid;grid-template-columns:130px minmax(0,1fr) 250px;gap:30px;align-items:center;min-height:330px;padding:clamp(24px,5vw,54px);border:1px solid var(--line);border-radius:var(--radius-lg);background:radial-gradient(circle at 88% 20%,rgba(244,203,105,.13),transparent 22rem),linear-gradient(135deg,rgba(17,51,111,.72),rgba(4,17,43,.94));box-shadow:var(--shadow-lg)}

.editorial-empty-mark{display:grid;place-items:center;width:112px;height:112px;border:1px solid rgba(244,203,105,.5);border-radius:32px;background:rgba(244,203,105,.08);color:var(--gold);font-family:var(--ds-font-display);font-size:68px}

.editorial-empty h2{margin-bottom:10px}

.editorial-empty p:not(.eyebrow){max-width:600px;color:var(--muted)}

.editorial-empty ol{margin:0;padding:0;list-style:none}

.editorial-empty li{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}

.editorial-empty li:last-child{border:0}

.editorial-empty li strong{color:var(--gold);font-size:11px}

.editorial-empty li span{font-weight:800}

.standings-table tbody tr:nth-child(-n+4) td:first-child{box-shadow:inset 3px 0 #4e9cff}

.standings-table tbody tr:nth-last-child(-n+3) td:first-child{box-shadow:inset 3px 0 #ff7c7c}

.standings-table tbody tr{transition:background .16s ease}

.standings-table tbody tr:hover td{background:rgba(29,79,164,.3)}

.card,.home-rail a{border-radius:22px}

.home-rail a:hover{border-color:rgba(255,255,255,.22);box-shadow:inset 0 1px rgba(255,255,255,.08),0 22px 56px rgba(0,0,0,.22);transform:translateY(-2px)}

.home-rail a:hover{border-color:rgba(125,190,255,.5);box-shadow:inset 0 1px rgba(178,215,255,.12),0 24px 58px rgba(0,20,68,.3)}

.hero-season{border-color:rgba(167,116,22,.24);background:rgba(255,255,255,.62)}

.hero-season>span,.hero-season strong span,.eyebrow{color:#9a6912}

.home-rail a:hover{
  border-color:rgba(35,93,161,.2);
  box-shadow:inset 0 1px #fff,0 22px 48px rgba(32,49,73,.13);
}

.home-rail a:hover{
  border-color:rgba(40,58,59,.2);
  background:linear-gradient(115deg,rgba(255,255,255,.62),transparent 40%),rgba(181,250,255,.24);
  box-shadow:0 8px 4px #00000012,0 22px 28px #0000000e,inset 0 1px 4px #ffffff8a;
}

.home-next h3{text-transform:none}

.home-next h3>span{text-transform:uppercase}

/* Selettori classifica compatti: link testuali separati da una barra. */
.standings-switch{
  justify-content:flex-start;
  margin:18px 0 10px;
}

.standings-switch-separator{color:rgba(77,95,105,.55);font-weight:700}

/* Home: prossime partite più compatte, senza colonna Lettura. */
.home-next{
  padding:18px 20px;
}

.home-next-head{
  margin-bottom:12px;
}

/* Classifiche ordinabili: le colonne esistenti mantengono la stessa larghezza. */
.standings-table{width:calc(100% + 288px);min-width:1088px}

.standings-sort{display:block;width:100%;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;letter-spacing:inherit;text-align:inherit;text-transform:inherit;white-space:nowrap;cursor:pointer}

.standings-sort:focus-visible{outline:2px solid var(--gold);outline-offset:3px;border-radius:3px}

.standings-table tbody tr:nth-child(-n+4) td:first-child,.standings-table tbody tr:nth-last-child(-n+3) td:first-child{box-shadow:none}

/* Archivio 2025/26: cambio vista senza scorrimento e colonna ordinata ben riconoscibile. */
.standings-scope-switch{display:flex;align-items:center;justify-content:flex-start;gap:10px;margin:12px 0 10px}

.home-standings [data-standings-scope-panel]{margin-top:0}

.home-standings [data-standings-scope-panel="general"]{padding-top:10px}

.standings-table th.standings-column-active{background:#174f91;color:#fff;box-shadow:inset 1px 0 rgba(255,255,255,.16),inset -1px 0 rgba(255,255,255,.16)}

.standings-table td.standings-column-active{background:rgba(47,117,197,.13);color:#123f70;box-shadow:inset 1px 0 rgba(47,117,197,.12),inset -1px 0 rgba(47,117,197,.12)}

.standings-table tbody tr:hover td.standings-column-active{background:rgba(47,117,197,.22)}

.standings-table tbody tr.standing-zone-champion td:first-child{box-shadow:inset 3px 0 var(--gold)}

.standings-table tbody tr.standing-zone-top td:first-child{box-shadow:inset 3px 0 #4e9cff}

.standings-table tbody tr.standing-zone-europa td:first-child{box-shadow:inset 3px 0 #27d17f}

.standings-table tbody tr.standing-zone-conference td:first-child{box-shadow:inset 3px 0 #f59e0b}

.standings-table tbody tr.standing-zone-bottom td:first-child{box-shadow:inset 3px 0 #dc2626}

body[data-page="home"] #app>.hero{
  display:flex;
  min-height:clamp(200px,20vw,270px);
  padding:clamp(22px,3vw,36px) clamp(22px,4vw,52px);
  border:0;
  background:linear-gradient(90deg,rgba(5,16,30,.91),rgba(5,16,30,.76) 39%,rgba(5,16,30,.18) 72%,transparent),url("../assets/images/optimized/home-hero-1600.webp") center/cover no-repeat;
  box-shadow:inset 0 16px 34px rgba(5,16,30,.66),inset 0 0 44px rgba(5,16,30,.28);
}
body[data-page="home"] #app>.hero::before,
body[data-page="home"] #app>.hero::after{content:none}
body[data-page="home"] #app>section.hero h1{
  max-width:18ch;
  font-family:var(--ds-font-display);
  font-size:clamp(32px,4.6vw,62px);
  font-weight:400;
  line-height:1.02;
  letter-spacing:-.015em;
  text-wrap:balance;
}
@media(max-width:760px){
  body[data-page="home"] #app>.hero{
    background-image:linear-gradient(90deg,rgba(5,16,30,.94),rgba(5,16,30,.76) 62%,rgba(5,16,30,.3)),url("../assets/images/optimized/home-hero-1600.webp");
    background-position:65% center;
  }
}
/* Dentro la stagione: stili confinati al solo dashboard della homepage. */
.home-dashboard .home-dashboard-grid{grid-template-columns:minmax(0,1fr);gap:32px}
.home-dashboard .home-next{min-width:0;padding:22px 24px 10px;border:0;background:transparent;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
.home-dashboard .home-next{display:grid;grid-template-columns:minmax(0,1fr);align-content:start}
.home-dashboard .home-next-panel h3{display:flex;align-items:center;justify-content:center;min-height:36px;margin:0 0 12px;padding-inline:44px}
.home-dashboard .home-next-panel[data-home-matchday-panel="current"],
.home-dashboard .home-matchday-nav{grid-area:1 / 1}
.home-dashboard .home-matchday-nav{justify-self:stretch;align-self:start;margin-inline:4%;z-index:2;pointer-events:none}
.home-dashboard .home-next h3{color:#142b3b;letter-spacing:0;text-transform:none}
.home-dashboard .home-next h3>strong{display:block;font-family:var(--ds-font-display);font-size:clamp(22px,1.8vw,27px);line-height:1.25;font-weight:700;letter-spacing:normal;white-space:nowrap}
body[data-page="home"] #app .home-dashboard .home-next h3>strong{font-size:clamp(18px,1.5vw,21px);font-weight:550;color:var(--ds-color-text-muted)}
.home-dashboard .home-matchday-nav{display:flex;justify-content:space-between;flex-shrink:0;gap:8px}
.home-dashboard .home-matchday-nav>.home-matchday-button{pointer-events:auto}
.home-dashboard .home-matchday-button{display:grid;place-items:center;width:36px;height:36px;min-height:36px;padding:0;border:1px solid var(--ds-color-border);border-radius:50%;background:#e6ebed;color:#283e4b;font:500 18px/1 Inter,sans-serif;box-shadow:inset 0 2px 5px rgba(20,43,59,.14);transform:none;transition:background-color .2s ease,box-shadow .2s ease,color .2s ease}
.home-dashboard .home-matchday-button:is(:hover,:focus-visible,:active):not(:disabled){border-color:var(--ds-color-border);background:#d8e2e7;color:#152e42;box-shadow:inset 0 2px 9px rgba(20,43,59,.12);transform:none}
.home-dashboard .home-matchday-button:disabled{opacity:.35}
.home-dashboard .home-match-list{border-top:1px solid #dce4e8}
.home-dashboard .home-match-row{grid-template-columns:minmax(110px,.65fr) minmax(0,1.8fr) 34px;gap:14px;padding:12px 0;border-bottom:1px solid #e3e9ed}
.home-dashboard .home-match-row:last-child{border-bottom:0}
.home-dashboard .home-match-meta time{color:#526777;font-size:11px}
.home-dashboard .home-match-teams{gap:8px;min-width:0}
.home-dashboard .home-match-teams .team-name{color:#142b3b;font-size:13px;font-weight:650;white-space:nowrap;overflow:visible;text-overflow:clip;line-height:1.3;overflow-wrap:normal}
.home-dashboard .home-match-teams .team-with-logo{gap:4px;flex-wrap:nowrap}
.home-dashboard .home-match-teams .team-logo{width:28px;height:28px;flex-basis:28px}
.home-dashboard .home-match-teams .home-match-score{color:#142b3b;font-size:14px;font-variant-numeric:tabular-nums}
.home-dashboard .home-match-row:has(a):hover{background:#edf2f4}
.home-dashboard .home-rail{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;min-width:0}
.home-dashboard .home-rail a{--home-card-shadow:rgba(20,43,59,.12);display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:14px;min-height:122px;min-width:0;padding:20px;border:1px solid var(--ds-color-border);border-radius:var(--ds-radius-panel);box-shadow:inset 0 2px 9px var(--home-card-shadow);transform:none;cursor:pointer;transition:box-shadow .2s ease}
.home-dashboard .home-rail .home-editorial-readings{background:#faf1d5;color:#503b13;border-color:#e8d9aa}
.home-dashboard .home-rail .home-editorial-teams{background:#e8f2ec;color:#164538;border-color:#c9ded2}
.home-dashboard .home-rail .home-editorial-champions{background:#e7f1fb;color:#183d64;border-color:#c8ddef}
.home-dashboard .home-rail strong{display:block;margin:0 0 5px;color:inherit;font-size:clamp(19px,1.7vw,25px);line-height:1.1;letter-spacing:-.03em}
.home-dashboard .home-rail small{display:block;color:inherit;font-size:13px;line-height:1.4;opacity:.85}
.home-dashboard .home-editorial-icon{width:38px;height:38px;color:inherit}
.home-dashboard .home-editorial-arrow{width:20px;height:20px}
.home-dashboard .home-rail a:hover{box-shadow:inset 0 2px 14px var(--home-card-shadow)}
.home-dashboard :is(a,button):focus-visible{outline:3px solid #b2811d;outline-offset:4px}
@media(max-width:1000px){
 .home-dashboard .home-rail a{gap:10px;padding:14px}
}
@media(max-width:760px){
 .home-dashboard .home-rail{grid-template-columns:1fr;gap:12px}
 .home-dashboard .home-rail a{padding:16px;min-height:104px}
}
 .home-dashboard .home-rail .home-card-full-title{color:inherit;font:inherit;letter-spacing:inherit;text-transform:none}
 .home-dashboard .home-rail .home-card-mobile-title{display:none}
@media(max-width:760px){
 body[data-page="home"] .home-dashboard .home-rail{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:1fr;gap:12px}
 .home-dashboard .home-rail .home-editorial-readings{grid-column:1 / -1}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams){position:relative;grid-template-columns:minmax(0,1fr);justify-items:center;align-content:center;gap:10px;padding:16px;min-height:104px;text-align:center}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams)>.home-editorial-icon{grid-area:1 / 1;width:28px;height:28px}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams)>.home-editorial-arrow{position:absolute;top:16px;right:16px}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams)>div{grid-area:2 / 1}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams) strong{margin:0}
 body[data-page="home"] #app .home-rail :is(.home-editorial-champions,.home-editorial-teams) strong{font-size:20px}
 .home-dashboard .home-rail :is(.home-editorial-champions,.home-editorial-teams) small{display:none}
 .home-dashboard .home-rail .home-card-full-title{display:none}
 .home-dashboard .home-rail .home-card-mobile-title{display:inline;color:inherit;font:inherit;letter-spacing:inherit;text-transform:none}
}
@media(max-width:580px){
 .home-dashboard .home-dashboard-grid{gap:24px}
 .home-dashboard .home-next{padding:18px 14px 6px}
 .home-dashboard .home-match-row{grid-template-columns:minmax(0,1fr) 34px;gap:7px 8px;padding:10px 0}
 .home-dashboard .home-match-meta{grid-column:1}
 .home-dashboard .home-match-teams{grid-column:1}
 .home-dashboard .home-match-reading,.home-dashboard .home-match-reading-placeholder{grid-column:2;grid-row:1 / span 2}
 .home-dashboard .home-match-meta time{font-size:11px}
 .home-dashboard .home-match-teams .team-name{font-size:12px}
}
@media(prefers-reduced-motion:reduce){.home-dashboard .home-rail a,.home-dashboard .home-matchday-button{transition:none}}

/* Colonna Lettura sempre visibile, anche senza hover e su touch. */
