.champions-goal-forecast{margin:18px 0 26px;border-color:rgba(139,211,255,.26)!important;background:linear-gradient(145deg,rgba(7,67,151,.88),rgba(2,24,69,.94))!important;box-shadow:inset 0 1px rgba(255,255,255,.07),0 18px 44px rgba(0,8,37,.2)!important;color:#fff}
