.champions-combined-volume{grid-template-columns:minmax(170px,.38fr) minmax(0,1.62fr)}
.champions-combined-volume dl{grid-template-columns:repeat(5,minmax(0,1fr))}
.champions-combined-volume .champions-goal-explainer{grid-column:1/-1;margin:0;color:#a8cce7;font-size:10px;line-height:1.55}
.champions-surprise-factor{min-width:0}
.champions-surprise-factor>span{display:flex;align-items:center;gap:6px}
