.champions-surprise-bar>b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#48cae4,#f6c453,#ff6b6b);box-shadow:0 0 12px rgba(246,196,83,.3)}
.champions-surprise-factor details{margin-top:9px;padding-top:8px;border-top:1px solid rgba(255,255,255,.13)}
.champions-surprise-factor summary{cursor:pointer;color:#d8eeff;font-size:11px;font-weight:750}
.champions-surprise-factor ul{display:grid;gap:5px;margin:8px 0 0;padding-left:16px;color:#d8eeff;font-size:10px;line-height:1.45}
.champions-surprise-components{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-top:8px}
.champions-surprise-components span{display:flex;justify-content:space-between;gap:5px;padding:5px 6px;border-radius:6px;background:rgba(15,86,171,.24)}
.champions-surprise-components small,.champions-surprise-components b{font-size:9px}
.champions-surprise-factor details p{margin:7px 0 0;color:#a8cce7;font-size:9px;line-height:1.4}
.champions-reading-market-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.champions-reading-market-panel{min-height:0}
.champions-reading-market-panel>span{color:#7fdcff}
