.champions-reading-market-list{display:grid;gap:8px;margin-top:16px}
.champions-reading-market-list article{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:4px 12px;padding:12px;border:1px solid rgba(139,211,255,.13);border-radius:14px;background:rgba(1,17,55,.42)}
