.champions-reading-validation{padding:26px;border:1px solid rgba(141,196,255,.22);border-radius:26px;background:rgba(3,23,70,.58)}
.champions-squads-detail{margin-bottom:46px}
.champions-team-hero{display:flex;align-items:center;justify-content:space-between;gap:30px;padding:38px 42px;border:1px solid rgba(121,207,255,.35);border-radius:30px;background:radial-gradient(circle at 78% 22%,rgba(29,122,214,.36),transparent 40%),linear-gradient(145deg,#073d8e,#02143f);box-shadow:0 24px 70px rgba(0,7,39,.3)}
.champions-team-hero .eyebrow{margin:0 0 7px;color:#83dfff}
.champions-team-hero h1{margin:0;color:#fff;font-family:var(--font-display);font-size:clamp(48px,7vw,84px);font-weight:400;line-height:.95;text-transform:uppercase}
.champions-team-hero>div:first-child>p:last-child{margin:12px 0 0;color:#a7c9e6;font-size:11px}
.champions-team-hero>div:last-child{display:grid;min-width:130px;padding:17px;border:1px solid rgba(127,224,255,.18);border-radius:18px;background:rgba(1,17,55,.5);text-align:center}
