.champions-team-hero>div:last-child strong{color:#fff;font-family:var(--ds-font-data);font-variant-numeric:tabular-nums;font-size:42px;font-weight:400}
.champions-team-status{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-top:14px}
.champions-team-status article,.champions-team-overview article{display:grid;align-content:start;gap:4px;padding:14px;border:1px solid rgba(132,199,255,.17);border-radius:13px;background:rgba(2,28,76,.72)}
.champions-team-status small,.champions-team-overview small{color:#79b7df;font-size:7px;font-weight:900;text-transform:uppercase}
.champions-team-status strong,.champions-team-overview strong{color:#e8f7ff;font-size:11px}
.champions-team-status span,.champions-team-overview span{color:#7899b8;font-size:8px;line-height:1.4}
.champions-team-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:8px}
.champions-team-overview a{margin-top:5px;color:#83dfff;font-size:8px;font-weight:900;text-decoration:none;text-transform:uppercase}
.champions-team-volume{margin:18px 0 28px;padding:26px;border:1px solid rgba(141,196,255,.24);border-radius:24px;background:rgba(3,23,70,.72)}
.champions-team-volume>header{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:16px}
