.champions-team-volume thead th{color:#77b9e5;font-size:7px;font-weight:900;text-transform:uppercase}
.champions-team-volume tbody th{color:#eef9ff;font-size:10px}
.champions-team-volume.is-unavailable{border-style:dashed}
.champions-team-attack{margin:18px 0 28px;padding:26px;border:1px solid rgba(127,220,255,.28);border-radius:24px;background:linear-gradient(145deg,rgba(5,47,108,.78),rgba(2,24,66,.78))}
.champions-team-attack>header,.champions-team-attack>footer{display:flex;align-items:end;justify-content:space-between;gap:24px}
.champions-team-attack>header{margin-bottom:16px}
