.champions-team-players table{width:100%;border-collapse:collapse;color:#b8d2e7;font-size:9px}
.champions-team-players th,.champions-team-players td{padding:9px 10px;border-bottom:1px solid rgba(139,211,255,.1);text-align:left}
.champions-team-players thead th{color:#77b9e5;font-size:7px;font-weight:900;text-transform:uppercase}
