.champions-player-stats-table tbody th span{display:block}
.champions-player-stats-table tbody th small{display:block;margin-top:3px;color:#6f9bbd;font-size:7px;font-weight:700}
.champions-player-stats-note{margin:16px 0 0;color:#7fa4c2;font-size:8px;line-height:1.55}
.champions-squads{margin-top:34px;padding:30px;border:1px solid rgba(141,196,255,.28);border-radius:30px;background:linear-gradient(145deg,rgba(4,38,99,.86),rgba(2,18,57,.94));box-shadow:0 24px 70px rgba(0,7,39,.24)}
