.champions-squad-card>summary strong{color:#fff;font-size:16px}
.champions-squad-card>summary>span:last-child{color:#8aa9c6;font-size:8px;font-weight:850;text-transform:uppercase}
.champions-squad-card>summary::after{content:"+";display:grid;width:26px;height:26px;flex:0 0 26px;place-items:center;border:1px solid rgba(145,201,255,.2);border-radius:50%;color:#fff}
