.champions-squad-meta p strong{color:#dff3ff}
.champions-squad-meta>span{display:flex;gap:8px}
.champions-squad-meta a{color:#7fdcff;font-size:8px;font-weight:850;text-decoration:none;text-transform:uppercase}
.champions-squad-alert{margin:0 0 12px;padding:10px 12px;border-left:3px solid #f2c45f;border-radius:7px;background:rgba(148,103,7,.16);color:#d4c49f;font-size:9px;line-height:1.5}
