.champions-squad-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.champions-squad-group h4{display:flex;align-items:center;justify-content:space-between;margin:0 0 6px;color:#7fdcff;font-size:8px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
