.champions-squad-group ul{display:grid;gap:4px;margin:0;padding:0;list-style:none}
.champions-squad-group li{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px;min-height:24px;padding:3px 7px;border-radius:6px;background:rgba(15,66,127,.22);color:#d9ecf8;font-size:8px}
.champions-squad-group li em{padding:2px 4px;border-radius:4px;background:rgba(75,196,231,.14);color:#88e2f8;font-size:6px;font-style:normal;font-weight:900;text-transform:uppercase}
.champions-squad-footnote{margin:14px 0 0;color:#7899b8;font-size:9px;line-height:1.5}
.champions-calendar{margin-top:34px;padding:32px;border:1px solid rgba(137,194,255,.24);border-radius:30px;background:rgba(3,23,70,.62);box-shadow:0 24px 70px rgba(0,7,39,.25);backdrop-filter:blur(18px)}
