.champions-calendar-heading{display:flex;align-items:end;justify-content:space-between;gap:30px}
.champions-calendar-heading>div{max-width:760px}
.champions-calendar-heading h2{margin-bottom:8px}
.champions-calendar-heading p:last-child{margin:0;color:#b8cdea}
.champions-calendar-heading>a{flex:none;padding:10px 14px;border:1px solid rgba(147,205,255,.3);border-radius:999px;background:rgba(8,58,145,.62);color:#eaf5ff;font-size:11px;font-weight:850;text-decoration:none}
.champions-calendar-heading>a:hover{background:rgba(22,90,194,.76)}
.champions-controls{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:12px;align-items:end;margin-top:28px;padding:16px;border:1px solid rgba(139,198,255,.19);border-radius:20px;background:rgba(1,14,50,.5)}
