.champions-results-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:26px 0 14px;color:#a9c3e6;font-size:11px}
.champions-results-head p{margin:0;text-transform:capitalize}
.champions-results-head strong{color:#fff;font-size:18px}
.champions-results-head>span{font-weight:700}
.champions-fixture-day{margin-top:22px}
.champions-fixture-day>header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:10px;padding:0 4px}
