.champions-fixture.match.fixture-card{overflow:hidden;border:1px solid rgba(144,201,255,.2);border-radius:17px;background:linear-gradient(145deg,rgba(16,67,153,.68),rgba(3,26,79,.82));box-shadow:inset 0 1px rgba(255,255,255,.07)}
