.rd-spatial-context-grid h4{margin:0 0 10px;font-size:17px}
.rd-spatial-context-status{font-size:13px;font-weight:600;line-height:1.6;color:var(--rd-accent)}
.rd-spatial-context-grid dl{font-size:12px;margin:14px 0;line-height:1.5}
.rd-spatial-context-grid dl>div{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:10px;padding:7px 0;border-bottom:1px solid var(--rd-line)}
.rd-spatial-context-grid dt{color:var(--rd-muted);overflow-wrap:anywhere}
.rd-spatial-context-grid dd{margin:0;overflow-wrap:anywhere;text-align:right}
.rd-spatial-context-grid article>p:last-child{font-size:12px;line-height:1.6}
