.rd-spatial-heading p{max-width:85ch;line-height:1.65;font-size:14px}
.rd-spatial-directions{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}
.rd-spatial-directions button{padding:10px 16px;border:1px solid var(--rd-line);border-radius:6px;background:transparent;color:var(--rd-ink);font:inherit;font-size:13px;cursor:pointer;min-height:44px}
