.rd-spatial-directions button:focus-visible,.rd-spatial select:focus-visible{outline:2px solid var(--rd-accent);outline-offset:3px}
.rd-spatial-samples{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;color:var(--rd-muted);font-size:12px;line-height:1.6}
