.rd-spatial-map-controls select{margin-left:6px;padding:8px;border:1px solid var(--rd-line);border-radius:4px;background:var(--rd-bg);color:var(--rd-ink);font:inherit;min-height:44px}
.rd-spatial-pitch{display:block;width:100%;max-width:760px;height:auto;margin:0 auto}
