.rd-forecasts .rd-forecast-destination{display:inline-block;margin-top:var(--ds-space-3);font:500 12px/1.5 var(--ds-font-body);color:var(--ds-color-accent)}
@media(max-width:600px){.rd-forecasts .rd-compact-forecast-table :is(th,td){padding:8px 3px;font-size:11px}
.rd-forecasts .rd-compact-forecast-table :is(th,td):nth-child(2){width:72px}
