  font-size:var(--ds-title-page);
  font-weight:650;
  text-transform:none;
  line-height:var(--ds-leading-title);
  overflow-wrap:anywhere;
}
body #app>.loading h1,
body #team-squad-app>.loading h1{color:var(--ds-color-text)}
body #app>.page-heading{
  min-height:0;
  margin:0 0 var(--ds-space-6);
  padding:0;
  border:0;
  border-radius:0;
  background:none;
  box-shadow:none;
  text-align:left;
  align-items:start;
