/* tokens.css: original cascade position */
:root{
  --ds-font-body:"Inter","Segoe UI",Arial,sans-serif;
  --ds-font-display:"Newsreader",Georgia,serif;
  --ds-font-data:var(--ds-font-body);
  --ds-text-meta:12px;
  --ds-text-compact:14px;
  --ds-text-body:16px;
  --ds-title-page:clamp(40px,4vw,48px);
  --ds-title-hero:clamp(40px,6vw,76px);
  --ds-title-section:clamp(24px,3vw,32px);
  --ds-title-subsection:20px;
  --ds-leading-body:1.55;
  --ds-leading-title:1.15;
  --ds-space-1:4px;
  --ds-space-2:8px;
  --ds-space-3:12px;
  --ds-space-4:16px;
  --ds-space-5:24px;
  --ds-space-6:32px;
  --ds-space-7:48px;
  --ds-space-8:64px;
  --ds-content-max:1050px;
  --ds-page-gutter:24px;
  --ds-radius-control:8px;
  --ds-radius-card:16px;
  --ds-radius-panel:24px;
  --ds-radius-pill:999px;
  --ds-border-width:1px;
  --ds-control-min-height:44px;
  --ds-control-font-size:14px;
  --ds-control-padding-block:10px;
  --ds-control-padding-inline:16px;
  --ds-glass-blur:blur(22px) saturate(135%);
  --ds-transition-fast:.18s ease;
  --ds-transition-base:.28s cubic-bezier(.22,.8,.22,1);

  --ds-color-page:#F8F7F4;
  --ds-color-surface:#FFFFFF;
  --ds-color-surface-soft:#EEF4F6;
  --ds-color-text:#283A3B;
  --ds-color-text-muted:#52666D;
  --ds-color-border:#D6E1E5;
  --ds-color-accent:#1E5F9D;
  --ds-color-accent-strong:#164C82;
  --ds-color-on-accent:#FFFFFF;
  --ds-color-focus:#1E5F9D;
  --ds-color-glass:rgba(220,233,236,.78);
  --ds-color-glass-border:rgba(255,255,255,.68);
  --ds-shadow-card:0 8px 24px rgba(20,43,59,.09),inset 0 1px rgba(255,255,255,.2);
  --ds-shadow-floating:0 20px 48px rgba(20,43,59,.16);
  --ds-page-background:
    radial-gradient(ellipse 85vw 90vh at 105% 8%,rgba(234,243,245,.78),transparent 78%),
    radial-gradient(ellipse 78vw 85vh at -12% 68%,rgba(245,241,235,.72),transparent 80%),
    radial-gradient(ellipse 70vw 80vh at 70% 112%,rgba(233,236,235,.48),transparent 82%),
    radial-gradient(ellipse 65vw 75vh at 30% -18%,rgba(255,255,255,.85),transparent 82%);
}
body[data-reading-detail-theme="champions"],body[data-competition-theme="champions"]{
  --ds-color-page:#07152C;
  --ds-color-surface:#10233F;
  --ds-color-surface-soft:#142D4D;
  --ds-color-text:#F2F6FF;
