body :is(#app,#team-squad-app) .team-comparator-options{gap:8px}
body :is(#app,#team-squad-app) .team-comparator-options select{font-size:11px;padding-left:8px;padding-right:24px}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparator-head{grid-template-columns:minmax(0,1fr) 26px minmax(0,1fr);gap:8px;margin-bottom:20px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs{font-size:11px;gap:0;margin-top:24px;justify-content:center}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::before,body :is(#app,#team-squad-app) .comparator-editorial .comparison-vs::after{display:none}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details h3{font-size:17px}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details :is(p,strong){font-size:11px}
body :is(#app,#team-squad-app) .comparator-editorial input{font-size:11px;padding:8px 24px 8px 8px;height:40px}
body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::after{right:9px;top:13px;width:9px;height:9px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-row{grid-template-columns:26px minmax(0,1fr) 94px minmax(0,1fr) 26px;gap:6px;padding:12px 8px;min-height:52px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-row>strong{font-size:13px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-label{font-size:11px}
body :is(#app,#team-squad-app) .comparator-editorial .comparison-track{height:6px}}
body :is(#app,#team-squad-app) .comparator-editorial .player-comparison-details h3{font-weight:700!important}
body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::before{content:"";position:absolute;right:12px;top:26px;width:6px;height:1.5px;background:#43595b;transform:rotate(45deg);pointer-events:none}
@media(max-width:700px){body :is(#app,#team-squad-app) .comparator-editorial .player-autocomplete::before{right:6px;top:23px;width:5px}}
body :is(#app,#team-squad-app) .team-comparator-toolbar h2{padding-top:0;font-family:var(--ds-font-display);font-size:var(--ds-title-section);font-weight:400!important;line-height:1.18;letter-spacing:.025em}
body :is(#app,#team-squad-app) .team-comparator-toolbar h2::before{content:none}
body :is(#app,#team-squad-app) .comparator-editorial input{color:#000!important;-webkit-text-fill-color:#000}
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button strong,
body :is(#app,#team-squad-app) .comparator-editorial .player-suggestions button:is(:hover,:focus-visible,.active) strong{color:#000;-webkit-text-fill-color:#000}
body :is(#app,#team-squad-app) .comparator-editorial .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
body :is(#app,#team-squad-app) .comparator-editorial .team-comparator-toolbar{width:100%;box-sizing:border-box}
body :is(#app,#team-squad-app) .comparator-editorial .team-comparator-toolbar h2{flex:1 1 auto}
body :is(#app,#team-squad-app) .comparator-editorial .team-comparator-options{flex:0 1 auto;max-width:100%}
body[data-page="player-stats"] #app>.player-comparator.comparator-editorial{display:block}

css/pages/readings-detail.css:
/* tokens.css: original cascade position */
:root{
  --ds-font-body:"Inter","Segoe UI",Arial,sans-serif;
  --ds-font-display:"Newsreader",Georgia,serif;
  --ds-font-data:var(--ds-font-body);
  --ds-text-meta:12px;
  --ds-text-compact:14px;
  --ds-text-body:16px;
  --ds-title-page:clamp(40px,4vw,48px);
  --ds-title-hero:clamp(40px,6vw,76px);
  --ds-title-section:clamp(24px,3vw,32px);
  --ds-title-subsection:20px;
  --ds-leading-body:1.55;
  --ds-leading-title:1.15;
  --ds-space-1:4px;
  --ds-space-2:8px;
  --ds-space-3:12px;
  --ds-space-4:16px;
  --ds-space-5:24px;
  --ds-space-6:32px;
  --ds-space-7:48px;
  --ds-space-8:64px;
  --ds-content-max:1050px;
  --ds-page-gutter:24px;
  --ds-radius-control:8px;
  --ds-radius-card:16px;
  --ds-radius-panel:24px;
  --ds-radius-pill:999px;
  --ds-border-width:1px;
  --ds-control-min-height:44px;
  --ds-control-font-size:14px;
  --ds-control-padding-block:10px;
  --ds-control-padding-inline:16px;
  --ds-glass-blur:blur(22px) saturate(135%);
  --ds-transition-fast:.18s ease;
  --ds-transition-base:.28s cubic-bezier(.22,.8,.22,1);

  --ds-color-page:#F8F7F4;
  --ds-color-surface:#FFFFFF;
  --ds-color-surface-soft:#EEF4F6;
  --ds-color-text:#283A3B;
  --ds-color-text-muted:#52666D;
  --ds-color-border:#D6E1E5;
  --ds-color-accent:#1E5F9D;
  --ds-color-accent-strong:#164C82;
  --ds-color-on-accent:#FFFFFF;
  --ds-color-focus:#1E5F9D;
  --ds-color-glass:rgba(220,233,236,.78);
  --ds-color-glass-border:rgba(255,255,255,.68);
  --ds-shadow-card:0 8px 24px rgba(20,43,59,.09),inset 0 1px rgba(255,255,255,.2);
  --ds-shadow-floating:0 20px 48px rgba(20,43,59,.16);
  --ds-page-background:
    radial-gradient(ellipse 85vw 90vh at 105% 8%,rgba(234,243,245,.78),transparent 78%),
    radial-gradient(ellipse 78vw 85vh at -12% 68%,rgba(245,241,235,.72),transparent 80%),
    radial-gradient(ellipse 70vw 80vh at 70% 112%,rgba(233,236,235,.48),transparent 82%),
    radial-gradient(ellipse 65vw 75vh at 30% -18%,rgba(255,255,255,.85),transparent 82%);
}
body[data-reading-detail-theme="champions"],body[data-competition-theme="champions"]{
  --ds-color-page:#07152C;
  --ds-color-surface:#10233F;
  --ds-color-surface-soft:#142D4D;
  --ds-color-text:#F2F6FF;
  --ds-color-text-muted:#AFC3DC;
  --ds-color-border:#304762;
  --ds-color-accent:#71B8FF;
  --ds-color-accent-strong:#0D55CB;
  --ds-color-focus:#9EDBFF;
  --ds-color-glass:rgba(16,35,63,.86);
  --ds-color-glass-border:rgba(147,200,255,.24);
  --ds-shadow-card:0 8px 24px rgba(0,7,28,.2),inset 0 1px rgba(255,255,255,.08);
  --ds-shadow-floating:0 20px 48px rgba(0,7,28,.38);
  --ds-page-background:
    radial-gradient(ellipse at 70% -10%,#153964 0,transparent 45rem),
    radial-gradient(ellipse at 0% 55%,#102747 0,transparent 40rem);
}
@media(max-width:600px){:root{--ds-page-gutter:16px}}
/* team-match-history.css: original cascade position */
.team-match-history{min-width:0;max-width:100%;margin:24px 0;padding:20px;border:1px solid #dbe2e8;border-radius:12px;background:#fff;color:#17283b}
[data-xgot-statistics]{min-width:0;max-width:100%}
[data-xgot-statistics] table{width:100%;table-layout:fixed}
[data-xgot-statistics] th,[data-xgot-statistics] td{white-space:normal!important;overflow-wrap:anywhere;padding:8px 5px!important}
.team-match-history h3{margin:0 0 8px;font-size:20px}
.team-match-history p{font-size:13px;line-height:1.5;color:#526174}
.team-history-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}
.team-history-scroll table{border-collapse:collapse;width:100%;min-width:980px;font-size:13px}
.team-history-scroll th,.team-history-scroll td{padding:10px;text-align:left;border-bottom:1px solid #e1e7ed;white-space:nowrap}
.team-history-scroll thead th{background:#eff3f7;font-weight:700}
.team-history-scroll:focus-visible{outline:2px solid #174fa5;outline-offset:3px}
.reading-competition-context{margin-top:24px;padding-top:20px;border-top:1px solid #dbe2e8;min-width:0}
.reading-competition-context p{font-size:13px;line-height:1.6;color:#526174}







@media(max-width:600px){.team-match-history{padding:12px;margin:16px 0}
.team-match-history h3{font-size:18px}}
/* base.css: original cascade position */
:root{--bg:#07110f;--surface:#101b18;--surface2:#162521;--line:#284039;--text:#f4f7f5;--muted:#9db0a9;--accent:#27d17f;--gold:#f2c14e;--danger:#ff6b6b;--max:var(--ds-content-max);--page-gutter:24px;--container-width:min(var(--max),calc(100% - 2 * var(--page-gutter)));color-scheme:dark;font-family:Inter,Segoe UI,Arial,sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:radial-gradient(circle at 80% 0,#16392c 0,transparent 28rem),var(--bg);color:var(--text);line-height:1.55}
a{color:inherit}
h1{max-width:850px;margin:0;font-size:clamp(38px,6vw,76px);line-height:1.02;letter-spacing:-.045em}
h2{margin:0 0 18px;font-size:clamp(25px,3vw,38px);letter-spacing:-.025em}
h3{margin:0 0 9px}
body{background:radial-gradient(circle at 82% -5%,rgba(35,91,180,.72) 0,transparent 31rem),radial-gradient(circle at 5% 55%,rgba(15,60,132,.38) 0,transparent 36rem),var(--bg)}
html{scroll-padding-top:100px}
body{background:radial-gradient(circle at 85% -8%,rgba(33,88,181,.62),transparent 34rem),radial-gradient(circle at -10% 52%,rgba(20,67,147,.32),transparent 34rem),linear-gradient(180deg,#03102d 0,var(--bg) 60%,#020819 100%);font-feature-settings:"tnum" 1}
body::before{content:"";position:fixed;z-index:-1;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,black,transparent 70%)}
button,a,select,input{outline-offset:3px}
:focus-visible{outline:2px solid var(--gold)}
body{background:radial-gradient(circle at 76% -12%,rgba(57,91,153,.3),transparent 34rem),radial-gradient(circle at 5% 48%,rgba(23,56,112,.18),transparent 40rem),#050812;letter-spacing:-.006em}
body::before{display:none}
h1,h2,h3,strong{letter-spacing:-.025em}
h1{font-weight:720}
h2{font-weight:690}
body{background:radial-gradient(circle at 78% -10%,rgba(48,126,230,.52),transparent 34rem),radial-gradient(circle at -8% 48%,rgba(18,89,190,.32),transparent 40rem),linear-gradient(180deg,#06265b 0,#031a3d 48%,#02132f 100%)}
body{
  background:#e8e8e8;
  color:var(--text);
}
body::before{
  display:block;
  background:
    radial-gradient(circle at 80% -10%,rgba(31,100,184,.1),transparent 32rem),
    radial-gradient(circle at 4% 42%,rgba(183,132,31,.07),transparent 34rem);
  mask-image:none;
}
body{background:#e8e8e8;color:var(--glass-text)}
h1,h2,h3,h4,strong{color:var(--glass-text)}
h1,h2,h3,
.editorial-empty-mark{
  font-family:var(--font-display);
  font-weight:400!important;
  font-style:normal;
  letter-spacing:.025em!important;
  word-spacing:.06em;
}
:is(.hero-stat,.hero-season) strong{
  font-family:var(--ds-font-data);
  font-weight:700;
  font-variant-numeric:tabular-nums lining-nums;
}
:root{
  --background-page:var(--bg);
  --background-surface:var(--surface);
  --background-surface-strong:var(--surface2);
  --color-text:var(--text);
  --color-text-muted:var(--muted);
  --color-border:var(--line);
  --color-accent:var(--accent);
  --space-1:var(--ds-space-1);
  --space-2:var(--ds-space-2);
  --space-3:var(--ds-space-3);
  --space-4:var(--ds-space-4);
  --space-5:var(--ds-space-5);
  --space-6:var(--ds-space-6);
  --space-7:var(--ds-space-7);
  --max-width:var(--max);
  --transition-fast:var(--ds-transition-fast);
  --transition-base:var(--ds-transition-base);
}
:root{
 --glass-light-bg:rgba(220,233,236,.78);
 --glass-dark-bg:rgba(23,46,64,.92);
 --glass-light-border:rgba(255,255,255,.68);
 --glass-dark-border:rgba(255,255,255,.16);
 --glass-blur:blur(22px) saturate(135%);
 --glass-shadow:0 8px 24px rgba(20,43,59,.09),inset 0 1px rgba(255,255,255,.2);
 --glass-light-text:#283a3b;
 --glass-dark-text:#f4f7fa;
}
/* layout.css: original cascade position */
.site-header{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:24px;padding:16px max(20px,calc((100vw - var(--max))/2));border-bottom:1px solid var(--line);background:rgba(7,17,15,.94);backdrop-filter:blur(14px)}
.brand{display:flex;align-items:center;gap:11px;text-decoration:none;white-space:nowrap}
.brand-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:linear-gradient(145deg,var(--accent),#087845);color:#03150d;font-size:24px;font-weight:950}
.brand strong,.brand small{display:block}
.brand small{color:var(--muted);font-size:11px}
.site-nav{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:3px;margin-left:auto}
.page-link{padding:8px 9px;border-radius:7px;color:var(--muted);font-size:13px;text-decoration:none}
.page-link:hover,.page-link.active{background:var(--surface2);color:var(--text)}
.menu-button{display:none;margin-left:auto;padding:9px 13px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text)}
main{width:min(var(--max),calc(100% - 40px));min-height:75vh;margin:auto;padding:54px 0 80px}
.hero{display:grid;grid-template-columns:1.5fr .7fr;gap:28px;align-items:end;padding:36px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,rgba(39,209,127,.12),rgba(16,27,24,.95))}

.muted{color:var(--muted)}
.section{margin-top:48px}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.hero{border-color:#365b98;background:linear-gradient(135deg,rgba(23,79,165,.7),rgba(8,29,72,.96) 55%,rgba(181,126,27,.2));box-shadow:inset 0 1px rgba(255,255,255,.08),0 24px 70px rgba(0,8,35,.24)}

main{padding-top:44px}
.hero::after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(180deg,transparent 50%,rgba(0,7,28,.4)),radial-gradient(circle at 88% 18%,rgba(244,203,105,.18),transparent 28%)}
.hero h1{max-width:760px;font-size:clamp(44px,6.4vw,82px);letter-spacing:-.055em;text-wrap:balance}
.hero .lead{max-width:690px;margin-bottom:0;color:#e0e8f5;font-size:clamp(16px,1.6vw,20px)}
.section{margin-top:72px}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:22px}
.section-heading h2{margin:0}
body:not([data-page="home"]) .hero{display:flex;min-height:0;padding:32px 0 28px;overflow:visible;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none;box-shadow:none}
body:not([data-page="home"]) .hero::after{display:none}
body:not([data-page="home"]) .hero>div:first-child{width:100%}
