}
.site-header::after{
  content:"";
  position:absolute;
  z-index:-1;
  left:8%;
  right:8%;
  bottom:-28px;
  height:30px;
  border-radius:50%;
  background:#0000001c;
  filter:blur(20px);
  pointer-events:none;
}
.site-header>.brand,.site-header>.menu-button,.site-header>.site-nav{position:relative;z-index:1}
.brand{gap:10px}
