.reading-match-hero~.reading-info-grid>.round16-formations:has(.reading-dual-lineup){grid-column:1/-1;min-width:0;background:var(--glass-dark-bg);border:1px solid var(--glass-dark-border);box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);color:var(--glass-dark-text)}
