  --ds-space-1:4px;
  --ds-space-2:8px;
  --ds-space-3:12px;
  --ds-space-4:16px;
  --ds-space-5:24px;
  --ds-space-6:32px;
  --ds-space-7:48px;
  --ds-space-8:64px;
  --ds-content-max:1050px;
  --ds-page-gutter:24px;
  --ds-radius-control:8px;
  --ds-radius-card:16px;
  --ds-radius-panel:24px;
