 body[data-page="player-stats"] #app .global-player-table tbody td:nth-child(2),body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th:nth-child(2){width:175px;min-width:175px;max-width:175px}
 body[data-page="player-stats"] #app .player-ranking-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));overflow:visible;gap:12px}
 body[data-page="player-stats"] #app .player-ranking-filters>label:first-child{grid-column:1/-1}
}

/* Uniform numeric typography throughout the player ranking. */
body[data-page="player-stats"] #app .global-player-table tbody td,
body[data-page="player-stats"] #app .global-player-table :is(.global-leader-value,.global-leader-rate,.global-leader-rank){font-size:12px;line-height:1.45;font-variant-numeric:tabular-nums}
body[data-page="player-stats"] #app .global-player-table thead th{text-transform:uppercase}

/* Match the full squad table's row hover, including pinned cells. */
body[data-page="player-stats"] #app .global-player-table tbody tr:is(:hover,:focus-within)>td{background:#eaecea;color:#243a3b}

/* The squad roster highlights the pinned player identity in pale cyan. */
body[data-page="player-stats"] #app .global-player-table tbody tr:is(:hover,:focus-within)>td:nth-child(2){background:#d5f1f2}

/* Include the rank in the pinned identity hover and uppercase header controls. */
body[data-page="player-stats"] #app .global-player-table tbody tr:is(:hover,:focus-within)>td:nth-child(-n+2){background:#d5f1f2}
body[data-page="player-stats"] #app .global-player-table thead :is(th,.ranking-sort){text-transform:uppercase}

/* Separate player statistics from the comparison section. */
body[data-page="player-stats"] #app>.global-player-leaders+.player-comparator{margin-top:48px;padding-top:36px;border-top:1px solid #c5cdcf}
@media(max-width:700px){body[data-page="player-stats"] #app>.global-player-leaders+.player-comparator{margin-top:32px;padding-top:28px}}

/* Mobile player table: compact pinned identity and continuous opaque cells. */
@media(max-width:700px){
 body[data-page="player-stats"] #app .player-ranking-scroll{max-height:65svh;overflow:auto;overscroll-behavior-x:contain;overscroll-behavior-y:auto;-webkit-overflow-scrolling:touch;scrollbar-gutter:stable;background:#fff}
 body[data-page="player-stats"] #app .global-player-table,
 body[data-page="player-stats"] #app .global-player-table.goalkeeper-ranking-table{min-width:0;width:max-content;border-collapse:separate;border-spacing:0;background:#fff}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-rank{width:34px}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-player{width:136px}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-team{width:110px}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-base{width:60px}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-stat{width:72px}
 body[data-page="player-stats"] #app .global-player-table col.ranking-col-action{width:52px}
 body[data-page="player-stats"] #app .global-player-table :is(th,td){padding-inline:8px;line-height:18px;background-clip:border-box;border-inline:0;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table tbody td{height:56px;border:0;border-bottom:1px solid #dce2e3}
 body[data-page="player-stats"] #app .global-player-table tbody td:first-child,
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th:first-child{left:0;width:34px;min-width:34px;max-width:34px;padding-inline:3px;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table tbody td:nth-child(2),
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th:nth-child(2){left:34px;width:136px;min-width:136px;max-width:136px;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table thead tr:nth-child(2)>th{left:auto;width:auto;min-width:0;max-width:none;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th[colspan]{font-size:10px;letter-spacing:0;line-height:18px}
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th{border-bottom:0}
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th[rowspan],
 body[data-page="player-stats"] #app .global-player-table thead tr:nth-child(2)>th{border-bottom:1px solid #dce2e3}
 body[data-page="player-stats"] #app .global-player-table .global-leader-player{font-size:12px;line-height:18px}
 body[data-page="player-stats"] #app .global-player-table .global-leader-player>span{gap:3px}
 body[data-page="player-stats"] #app .global-player-table .global-leader-player strong{white-space:normal;overflow-wrap:anywhere;font-size:12px;line-height:18px}
 body[data-page="player-stats"] #app .global-player-table .global-leader-player small{margin-top:0;font-size:10px;line-height:14px}
 body[data-page="player-stats"] #app .global-player-table .global-leader-rank{min-width:24px;width:24px;height:24px;line-height:24px}
 body[data-page="player-stats"] #app .global-player-table .player-team{gap:5px;font-size:11px;white-space:normal}
 body[data-page="player-stats"] #app .global-player-table .player-team-badge{width:18px;height:18px;object-fit:contain}
}

/* Mobile continuity: use alternating fills instead of cell separator borders. */
@media(max-width:700px){
 body[data-page="player-stats"] #app .player-ranking-scroll{padding:0;background:#c5bdb6;box-shadow:none;border:1px solid #c5cdcf}
 body[data-page="player-stats"] #app .global-player-table :is(thead,tbody,tr){border:0;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table tbody tr>td{border:0;box-shadow:none;background-clip:border-box}
 body[data-page="player-stats"] #app .global-player-table thead tr>th,
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th[rowspan],
 body[data-page="player-stats"] #app .global-player-table thead tr:nth-child(2)>th{border:0;box-shadow:none;background-color:#c5bdb6}
 body[data-page="player-stats"] #app .global-player-table thead tr:nth-child(2)>th{height:40px;padding-block:6px}
 body[data-page="player-stats"] #app .global-player-table .ranking-sort{line-height:18px;padding-block:2px}
}

/* Plain ranking positions without circular badges. */
body[data-page="player-stats"] #app .global-player-table tbody tr .global-leader-rank{display:inline;background:none;border:0;border-radius:0;box-shadow:none;width:auto;min-width:0;height:auto;padding:0;line-height:inherit;color:#243a3b}

/* Paint and pin the mobile header as one continuous surface. */
@media(max-width:700px){
 body[data-page="player-stats"] #app .global-player-table thead{position:sticky;top:0;z-index:10;background:#c5bdb6;isolation:isolate}
 body[data-page="player-stats"] #app .global-player-table thead tr{background:#c5bdb6}
 body[data-page="player-stats"] #app .global-player-table thead tr>th,
 body[data-page="player-stats"] #app .global-player-table thead tr:nth-child(2)>th{position:static;top:auto;left:auto;background-color:#c5bdb6;border:0;outline:0;box-shadow:none}
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th:first-child{position:sticky;left:0;top:auto;z-index:12;background:#c5bdb6}
 body[data-page="player-stats"] #app .global-player-table thead tr:first-child>th:nth-child(2){position:sticky;left:34px;top:auto;z-index:12;background:#c5bdb6}
}

css/players.css:
/* players.css - modulo del sistema grafico condiviso. */
.squad-table td small{display:block;color:var(--muted,#667085)}

.squad-table .player-open{display:flex;align-items:center;gap:10px;min-width:205px;padding:0;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer}

.squad-table .player-open:hover strong,.squad-table .player-open:focus-visible strong{text-decoration:underline}

.player-detail{width:min(980px,calc(100% - 32px));max-height:90vh;padding:0;border:0;border-radius:20px;background:var(--card,#fff);color:inherit;box-shadow:0 24px 70px rgba(0,0,0,.28)}

.player-detail::backdrop{background:rgba(4,10,20,.68);backdrop-filter:blur(3px)}

#player-detail-content{padding:28px}

.player-detail-close{position:sticky;z-index:2;top:12px;float:right;width:40px;height:40px;border:1px solid var(--line,#d7dbe2);border-radius:50%;background:var(--card,#fff);color:inherit;font-size:1.65rem;line-height:1;cursor:pointer}

.player-profile-head{display:flex;align-items:center;gap:22px;padding-right:48px}

.player-profile-head h2{margin:6px 0;font-size:2rem}

.player-profile-head p{margin:4px 0;color:var(--muted,#667085)}



.player-bio-grid,.player-stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:22px 0}

.player-bio-grid>div,.player-stat-grid article,.player-competition-heading>div{padding:12px;border:1px solid var(--line,#e1e5ec);border-radius:12px;background:var(--surface,#f8f9fb)}

.player-bio-grid span,.player-stat-grid span,.player-competition-heading span{display:block;color:var(--muted,#667085);font-size:.75rem}

.player-bio-grid strong,.player-stat-grid strong,.player-competition-heading strong{display:block;margin-top:5px}

.player-detail section{margin-top:24px}

.player-detail section h3{margin-bottom:10px}

.player-competition-heading{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:22px}











.player-detail{border:1px solid var(--line);background:linear-gradient(155deg,var(--surface2),var(--surface));color:var(--text);box-shadow:0 24px 70px rgba(0,0,0,.45)}

.player-detail-close{background:var(--surface2);color:var(--text)}

.squad-table th:first-child,.squad-table td:first-child{text-align:left}

.squad-table thead th[rowspan]{vertical-align:middle}

.squad-table thead th[colspan]{border-left:1px solid var(--line);text-align:center}

.squad-table thead tr:nth-child(2) th{padding-top:6px;padding-bottom:8px;text-align:center;font-size:.68rem}

.squad-table-wrap{position:relative;max-height:min(72vh,760px);overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable}

.squad-table-wrap:focus-visible{outline:2px solid var(--gold);outline-offset:3px}

.squad-table{width:1621px;min-width:1621px;table-layout:fixed}

.squad-table .squad-col-player{width:235px}

.squad-table .squad-col-role{width:150px}

.squad-table .squad-col-market{width:120px}

.squad-table .squad-col-played{width:60px}

.squad-table .squad-col-minutes{width:76px}

.squad-table .squad-col-stat{width:70px}

.market-value{color:var(--gold);font-weight:800;text-decoration:none}

.market-value:hover{text-decoration:underline}

.player-market-panel{display:grid;grid-template-columns:1fr auto;gap:4px 18px;margin:16px 0;padding:15px 18px;border:1px solid rgba(243,201,105,.28);border-radius:14px;background:rgba(243,201,105,.08)}

.player-market-panel span{color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase}

.player-market-panel strong{grid-row:1/3;grid-column:2;color:var(--gold);font-size:24px}

.player-market-panel small{color:var(--muted)}

.squad-table thead th{position:sticky;top:0;z-index:4;background:var(--surface2);box-shadow:0 1px 0 var(--line)}

.squad-table thead tr:nth-child(2) th{top:42px}

.squad-table th:first-child,.squad-table td:first-child{position:sticky;left:0;min-width:235px;background:var(--surface);box-shadow:8px 0 14px -12px rgba(0,0,0,.9)}

.squad-table thead th:first-child{z-index:7;background:var(--surface2)}

.squad-table tbody tr:hover td,.squad-table tbody tr:focus-within td{background:rgba(181,250,255,.34);color:#283a3b}

.squad-table tbody tr:hover td:first-child,.squad-table tbody tr:focus-within td:first-child{box-shadow:8px 0 14px -10px rgba(0,0,0,.95)}

.squad-leaders{margin-top:34px;padding-top:28px;border-top:1px solid var(--line)}

.squad-leaders+.squad-leaders{margin-top:18px}

.squad-leaders-header{position:relative}

.squad-leaders-heading{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:16px}

.squad-leaders-header .squad-leaders-heading{margin-bottom:0}

.squad-leaders-heading>span:first-child{display:grid;gap:3px}

.squad-leaders-heading>span:first-child>strong{font-family:var(--ds-font-display);font-size:clamp(1.35rem,2.5vw,1.85rem);font-weight:400;letter-spacing:.01em}

.squad-leaders-heading>span:last-child{padding:6px 10px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.72rem;font-weight:800;white-space:nowrap}

.squad-leaders-heading h3{margin:0;font-size:clamp(1.35rem,2.5vw,1.85rem)}

.squad-leaders-heading p:last-child{max-width:520px;margin:0;color:var(--muted);font-size:.88rem}

.squad-leaders-content{margin-top:16px;padding-top:16px;border-top:1px solid var(--line)}

.squad-leaders-content>p{max-width:760px;margin:0 0 16px;color:var(--muted);font-size:.88rem}

.squad-leader-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}

.squad-leader-card{padding:16px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,rgba(23,79,165,.2),var(--surface));box-shadow:0 10px 24px rgba(0,7,31,.18)}

.squad-leader-card header{display:flex;justify-content:space-between;gap:12px;align-items:center;padding-bottom:11px;border-bottom:1px solid var(--line)}

.squad-leader-card h4{margin:0;color:#fff;font-size:1rem}

.squad-leader-card header span{color:var(--muted);font-size:.68rem;font-weight:900;text-transform:uppercase}

.squad-leader-card ol{margin:10px 0 0;padding:0;list-style:none}

.squad-leader-card li{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid rgba(65,104,165,.38)}

.squad-leader-card li:last-child{border:0;padding-bottom:0}

.leader-rank{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:rgba(65,104,165,.32);color:#dce8ff;font-size:.72rem;font-weight:900}

.squad-leader-card li:first-child .leader-rank{background:rgba(229,185,79,.2);color:#ffe59a}

.leader-player{overflow:hidden;padding:0;border:0;background:transparent;color:var(--text);font:inherit;font-weight:800;text-align:left;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}

.leader-player:hover,.leader-player:focus-visible{color:#ffe59a;text-decoration:underline}

.squad-leader-card li>strong{text-align:right;color:#fff;font-size:1.05rem}

.squad-leader-card li>strong small{display:block;color:var(--muted);font-size:.68rem;font-weight:700}

.leader-player-unlinked{cursor:default}

.leader-player-unlinked small{display:block;margin-top:2px;color:var(--muted);font-size:.62rem;font-weight:750;text-transform:uppercase}

.global-player-leaders{margin-top:72px;padding-top:38px;border-top:1px solid var(--line)}

.global-player-leaders-heading{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:20px}

.global-player-leaders-heading h2{margin-bottom:0}

.global-player-leaders-heading>p{max-width:560px;margin:0;color:var(--muted)}

.global-leaderboard-controls{display:grid;gap:8px;margin-bottom:12px;padding:10px 12px;border:1px solid var(--line);border-radius:11px;background:linear-gradient(145deg,rgba(23,79,165,.22),var(--surface))}

.global-leaderboard-caption{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 2px 10px}

.global-leaderboard-caption strong{color:#fff;font-size:1.08rem}

.global-leaderboard-caption span,.global-leaderboard-note{color:var(--muted);font-size:.8rem}

.global-player-table{width:100%;min-width:980px;table-layout:fixed}

.global-player-table .global-col-rank{width:54px}

.global-player-table .global-col-player{width:28%}

.global-player-table .global-col-team{width:17%}

.global-player-table .global-col-appearances{width:68px}

.global-player-table .global-col-minutes{width:86px}

.global-player-table .global-col-value{width:180px}

.global-player-table .global-col-rate{width:170px}

.global-player-table th:first-child,.global-player-table td:first-child{text-align:center}

.global-player-table th:nth-child(2),.global-player-table td:nth-child(2),.global-player-table th:nth-child(3),.global-player-table td:nth-child(3){text-align:left}

.global-player-table tbody tr:hover{background:rgba(23,79,165,.2)}

.global-leader-rank{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:rgba(65,104,165,.32);color:#dce8ff;font-size:.75rem;font-weight:900}

.global-player-table tr:first-child .global-leader-rank{background:rgba(229,185,79,.22);color:#ffe59a}

.global-leader-player{display:block;min-width:0;color:var(--text);text-decoration:none}

.global-leader-player>span{display:flex;align-items:center;min-width:0;gap:7px}

.global-leader-player>span>strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.global-leader-player:hover strong,.global-leader-player:focus-visible strong{color:#ffe59a;text-decoration:underline}

.global-leader-player small{display:block;color:var(--muted);font-size:.7rem}

.serie-b-marker{display:inline-flex;flex:0 0 auto;padding:2px 6px;border:1px solid rgba(244,207,114,.45);border-radius:999px;background:rgba(229,185,79,.12);color:#ffe59a;font-size:.62rem;font-weight:900;white-space:nowrap}

.global-leader-value{color:#ffe59a;font-size:1rem}

.global-leader-rate{color:#dce8ff;font-size:.92rem}

.global-leaderboard-note{margin:12px 2px 0}

.referee-card,.objective-card,.squad-leader-card{transition:border-color .18s ease,transform .18s ease}

.referee-card:hover,.objective-card:hover,.squad-leader-card:hover{border-color:var(--line-strong);transform:translateY(-2px)}

.card,.home-next,.home-rail a,.day-nav,.referee-controls,.editorial-empty,.cup-stage,.objective-card,.squad-leader-card,.pilot-section{border-color:rgba(255,255,255,.1);background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.035));box-shadow:inset 0 1px rgba(255,255,255,.055),0 16px 46px rgba(0,0,0,.16);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}

.team-stat-grid article,.player-bio-grid>div,.player-stat-grid article{border-color:rgba(255,255,255,.095);background:rgba(255,255,255,.045);box-shadow:inset 0 1px rgba(255,255,255,.035)}

.objective-card,.player-detail{border-radius:24px}

.squad-table thead th{background:#edf2f8}

.squad-table th:first-child,.squad-table td:first-child{background:#f8f9fb}

.season-overview strong,.squad-leader-card h4,.squad-leader-card li>strong,.objective-metric strong,.global-leaderboard-caption strong{color:#172033}

.leader-rank{background:rgba(20,89,166,.1);color:#1459a6}

.squad-leader-card li:first-child .leader-rank{background:rgba(167,116,22,.13);color:#8a5d0d}

.leader-player:hover,.leader-player:focus-visible,.global-leader-player:hover strong,.global-leader-player:focus-visible strong{color:#0d559f}

.global-leaderboard-controls{border-color:rgba(18,64,119,.1);background:rgba(255,255,255,.58)}

.global-leader-value{color:#8a5d0d}

.global-leader-rate{color:#174f91}

.serie-b-marker{border-color:rgba(167,116,22,.25);background:rgba(167,116,22,.08);color:#865a0d}

.player-detail,.player-detail-close{background:#f5f5f5;color:#172033}

.card p,.home-rail small,.objective-card p,.squad-leader-card span,.lineup-day>span,.lineup-day>small{color:var(--glass-muted)}

.table-wrap,.squad-table-wrap{
  border-color:var(--glass-border);
  background:rgba(255,255,255,.48);
  box-shadow:0 8px 4px #0000000d,0 22px 28px #0000000a,inset 0 1px 4px #ffffff8a;
  backdrop-filter:blur(18px);
  -webkit-backdrop-filter:blur(18px);
}

.squad-table thead th,.squad-table th:first-child,.squad-table td:first-child{background:rgba(247,253,253,.9)}

.objective-metric strong,.season-overview strong,.squad-leader-card h4,.squad-leader-card li>strong,.global-leaderboard-caption strong{color:var(--glass-text)}

.player-detail,.player-detail-close{border-color:var(--glass-border);background:#f4f7f7;color:var(--glass-text)}

.player-detail::backdrop{background:rgba(40,58,59,.42)}

.squad-table tbody tr:hover td:first-child,
.squad-table tbody tr:focus-within td:first-child{
  background:rgba(224,250,250,.96);
  box-shadow:8px 0 14px -10px rgba(40,58,59,.28);
}

.prediction-player-market{margin-top:14px;padding:16px;border:1px solid rgba(36,90,120,.12);border-radius:16px;background:rgba(255,255,255,.54)}

.prediction-player-market p{margin:5px 0 0;color:var(--muted);font-size:11px}

.probable-lineup-player{display:grid;justify-items:center;min-width:0;color:#fff;text-align:center}

.probable-lineup-player strong{max-width:125px;margin-top:7px;padding:6px 10px;border:1px solid rgba(255,255,255,.18);border-radius:10px;background:rgba(4,20,15,.82);box-shadow:0 7px 18px rgba(0,0,0,.22);font-size:.78rem;line-height:1.1}

.probable-lineup-player strong{color:#fff}

/* Top 15 calciatori: blocco unico, gerarchia e spaziature coordinate al sistema glass. */
.global-player-leaders{
  margin-top:72px;
  padding:30px;
  overflow:hidden;
  border:1px solid var(--glass-border);
  border-radius:28px;
  background:linear-gradient(118deg,rgba(255,255,255,.5),transparent 40%),linear-gradient(300deg,rgba(225,246,249,.32),transparent 58%),rgba(247,250,250,.5);
  box-shadow:0 8px 4px #0000000d,0 26px 42px rgba(32,49,73,.08),inset 0 1px 4px #ffffffa8;
  backdrop-filter:blur(20px) saturate(125%);
  -webkit-backdrop-filter:blur(20px) saturate(125%);
}

.global-player-leaders-heading{
  align-items:center;
  margin:0 0 22px;
  padding-bottom:22px;
  border-bottom:1px solid rgba(40,58,59,.11);
}

.global-player-leaders-heading h2{margin:0;line-height:1.08}

.global-player-leaders-heading>p{max-width:520px;font-size:.92rem;line-height:1.55}

.global-leaderboard-controls{
  margin:0;
  padding:12px 14px;
  border-radius:16px;
  box-shadow:inset 0 1px 3px #ffffff9c;
}

.global-period-group{padding-bottom:11px;border-bottom:1px solid rgba(40,58,59,.1)}

.global-period-button{border-color:rgba(167,116,22,.26);background:rgba(255,248,232,.46);color:#7a5718}

#global-player-leaderboard{margin-top:14px}

.global-leaderboard-caption{
  margin:0;
  padding:14px 16px;
  border:1px solid var(--glass-border);
  border-bottom:0;
  border-radius:18px 18px 0 0;
  background:rgba(255,255,255,.5);
  box-shadow:inset 0 1px 3px #ffffffa8;
}

.global-leaderboard-caption strong{font-size:1rem;letter-spacing:.01em}

.global-leaderboard-caption span{text-align:right}

#global-player-leaderboard .table-wrap{
  border-radius:0 0 18px 18px;
  box-shadow:0 14px 28px rgba(32,49,73,.07),inset 0 1px 3px #ffffff8a;
}

.global-player-table th{padding-top:13px;padding-bottom:13px;letter-spacing:.06em}

.global-player-table td{padding-top:14px;padding-bottom:14px}

.global-player-table tbody tr:nth-child(-n+3) td:first-child{background:rgba(255,247,226,.34)}

.global-player-table tr:nth-child(2) .global-leader-rank{background:rgba(36,90,120,.13);color:#365f78}

.global-player-table tr:nth-child(3) .global-leader-rank{background:rgba(167,116,22,.11);color:#8a641f}

.global-leader-player strong{font-size:.94rem}

.global-leader-player small{margin-top:2px}

.global-leaderboard-note{
  margin:14px 0 0;
  padding:11px 14px;
  border-left:3px solid rgba(167,116,22,.48);
  border-radius:0 12px 12px 0;
  background:rgba(255,255,255,.3);
  line-height:1.5;
}
.player-comparator{margin-top:28px;padding:26px;border:1px solid rgba(24,75,102,.14);border-radius:22px;background:linear-gradient(145deg,#f9fdff,#eaf5f7);box-shadow:0 18px 46px rgba(14,49,67,.08)}
.player-comparator>header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:18px}.player-comparator>header h2{margin:3px 0 0}.player-comparator>header>p{max-width:460px;margin:0;color:var(--muted);font-size:12px;line-height:1.55}
.player-comparator-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.team-player-comparator .player-comparator-controls{grid-template-columns:repeat(2,minmax(0,1fr))}
.player-comparator-controls label{display:grid;align-content:start;gap:7px;color:#36596a;font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.player-comparator-controls select,.player-comparator-controls input{width:100%;min-height:44px;padding:11px 12px;border:1px solid #7897a6;border-radius:11px;background:#fff;color:#102f3f;font:700 13px Inter,sans-serif}.player-comparator-controls input::placeholder{color:#607d8b;opacity:1}.player-comparator-controls select:focus-visible,.player-comparator-controls input:focus-visible{outline:3px solid rgba(9,105,130,.28);outline-offset:2px;border-color:#096982}.player-autocomplete{position:relative;display:block}.player-comparator-control-hint{color:#54717f;font-size:10px;font-weight:650;letter-spacing:0;line-height:1.35;text-transform:none}.player-suggestions{position:absolute;z-index:20;top:calc(100% + 6px);left:0;width:100%;max-height:272px;overflow-y:auto;padding:6px;border:1px solid #7897a6;border-radius:12px;background:#fff;box-shadow:0 16px 34px rgba(10,45,61,.2)}.player-suggestions[hidden]{display:none}.player-suggestions button{display:grid;width:100%;gap:2px;padding:10px;border:0;border-radius:8px;background:#fff;color:#163c4e;text-align:left;cursor:pointer}.player-suggestions button+button{margin-top:2px}.player-suggestions button:hover,.player-suggestions button:focus-visible,.player-suggestions button.active{outline:0;background:#123f66;color:#fff}.player-suggestions button strong{font-size:13px}.player-suggestions button small{color:#567381;font-size:10px}.player-suggestions button:hover small,.player-suggestions button:focus-visible small,.player-suggestions button.active small{color:#d8ecf5}.player-suggestions-empty{display:block;padding:12px;color:#526f7d;font-size:12px;font-weight:700;letter-spacing:0;text-transform:none}
.player-comparator-result{margin-top:16px}.player-comparator-head{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}.player-comparator-head article{padding:16px;border-radius:15px;background:#123f66;color:#fff}.player-comparator-head h3{margin:0;color:#fff;font-size:18px}.player-comparator-head p{margin:4px 0;color:#d7edf6;font-size:11px}.player-comparator-head strong{color:#fff;font-size:11px}
.player-comparator table{width:100%;border-collapse:collapse;background:#fff}.player-comparator th,.player-comparator td{padding:11px;border-bottom:1px solid rgba(24,75,102,.11);text-align:left}.player-comparator td strong,.player-comparator td small{display:block}.player-comparator td small{margin-top:3px;color:var(--muted);font-size:10px}
@media(max-width:700px){.player-comparator{padding:20px 14px}.player-comparator>header{align-items:flex-start;flex-direction:column}.player-comparator-controls,.team-player-comparator .player-comparator-controls{grid-template-columns:1fr}.player-comparator-head{grid-template-columns:1fr 1fr}.player-comparator table{min-width:560px}}
/* Statistiche squadre: superfici esplicite, senza coinvolgere le 20 card. */
body[data-page="team-stats"] :is(.player-comparator,.global-player-leaders,.global-leaderboard-controls){
 background:var(--glass-light-bg);border-color:var(--glass-light-border);color:var(--glass-light-text);
 box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
}
body[data-page="team-stats"] .player-comparator-head article{
 background:var(--glass-dark-bg);border:1px solid var(--glass-dark-border);color:var(--glass-dark-text);
 box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
}
body[data-page="team-stats"] .player-comparator-head :is(h3,p,strong){color:var(--glass-dark-text)}
body[data-page="team-stats"] :is(.player-comparator>header>p,.global-player-leaders-heading>p,.global-leaderboard-caption span,.global-leaderboard-note){color:#52636b}
body[data-page="team-stats"] .global-leaderboard-caption{background:rgba(255,255,255,.52);box-shadow:none}
body[data-page="team-stats"] :is(.player-comparator,.global-player-leaders) .table-wrap{
 background:rgba(255,255,255,.35);border-color:rgba(40,58,59,.14);box-shadow:0 14px 28px rgba(32,49,73,.07),inset 0 1px rgba(255,255,255,.54);
}
body[data-page="team-stats"] :is(.player-comparator table,.global-player-table){background:transparent;font-family:var(--font-body);font-variant-numeric:tabular-nums}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) :is(th,td){border-bottom:1px solid rgba(40,58,59,.1)}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) thead th{background:rgba(255,255,255,.52);color:#47575a;font-size:11px;font-weight:650;letter-spacing:.06em;text-transform:uppercase}
body[data-page="team-stats"] .player-comparator tbody th{background:transparent;color:#47575a;font-weight:650}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) tbody tr:nth-child(even){background:rgba(20,43,59,.025)}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) tbody tr:hover{background:rgba(181,250,255,.34)}
body[data-page="team-stats"] .player-comparator :is(th,td):nth-child(n+2){text-align:right}
body[data-page="team-stats"] .global-player-table :is(th,td):nth-child(n+4){text-align:center}
body[data-page="team-stats"] .global-leader-player strong{font-family:var(--font-body);font-size:14px;font-weight:800}
body[data-page="team-stats"] .global-player-leaders .global-stat-button{
 min-height:36px;padding:8px 16px;border:1px solid var(--glass-light-border);border-radius:999px;
 background:var(--glass-light-bg);color:var(--glass-light-text);box-shadow:var(--glass-shadow);
 backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
 font-size:.86rem;line-height:1.2;font-weight:700;transform:none;
 transition:background-color .2s ease,box-shadow .2s ease,color .2s ease;
}
body[data-page="team-stats"] .global-player-leaders .global-stat-button:hover{background-color:#e0ebf0;color:#152e42;transform:none}
body[data-page="team-stats"] .global-player-leaders .global-stat-button.active{background:var(--glass-dark-bg);border-color:var(--glass-dark-border);color:var(--glass-dark-text)}
body[data-page="team-stats"] .global-stat-group>div{display:flex;flex-wrap:wrap;gap:8px}
@media(prefers-reduced-motion:reduce){body[data-page="team-stats"] .global-player-leaders .global-stat-button{transition:none}}
/* Posizioni leggibili sulle righe chiare, preservando le tinte delle medaglie. */
body[data-page="team-stats"] .global-leader-rank{color:#294b61}
body[data-page="team-stats"] .global-player-table tr:first-child .global-leader-rank{color:#78520f}

css/reading-detail.css:
/* Shared reading presentation, isolated from calendars and the betslip. */
.rd-spatial-continuity{margin-bottom:24px;min-width:0}
.rd-spatial-context-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.rd-spatial-context-grid article{padding:16px;border:1px solid var(--rd-line);min-width:0}
.rd-spatial-context-grid h4{margin:0 0 10px;font-size:17px}
.rd-spatial-context-status{font-size:13px;font-weight:600;line-height:1.6;color:var(--rd-accent)}
.rd-spatial-context-grid dl{font-size:12px;margin:14px 0;line-height:1.5}
.rd-spatial-context-grid dl>div{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:10px;padding:7px 0;border-bottom:1px solid var(--rd-line)}
.rd-spatial-context-grid dt{color:var(--rd-muted);overflow-wrap:anywhere}
.rd-spatial-context-grid dd{margin:0;overflow-wrap:anywhere;text-align:right}
.rd-spatial-context-grid article>p:last-child{font-size:12px;line-height:1.6}
@media(max-width:640px){.rd-spatial-context-grid{grid-template-columns:1fr;gap:12px}}
.rd-spatial,.rd-spatial-synthesis{margin-top:28px;min-width:0}
.rd-spatial-heading h3,.rd-spatial-synthesis h3{margin:6px 0 12px;font-size:clamp(20px,3vw,28px)}
.rd-spatial-heading p,.rd-spatial-comment,.rd-spatial-synthesis p{max-width:85ch;line-height:1.65;font-size:14px}
.rd-spatial-directions{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}
.rd-spatial-directions button{padding:10px 16px;border:1px solid var(--rd-line);border-radius:6px;background:transparent;color:var(--rd-ink);font:inherit;font-size:13px;cursor:pointer;min-height:44px}
.rd-spatial-directions button[aria-pressed="true"]{border-color:var(--rd-accent);background:color-mix(in srgb,var(--rd-accent) 12%,transparent)}
.rd-spatial-directions button:focus-visible,.rd-spatial select:focus-visible,.rd-spatial-limits summary:focus-visible{outline:2px solid var(--rd-accent);outline-offset:3px}
.rd-spatial-samples{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;color:var(--rd-muted);font-size:12px;line-height:1.6}
.rd-spatial-samples p{margin:4px 0 12px;overflow-wrap:anywhere}
.rd-spatial-samples b{color:var(--rd-ink)}
.rd-spatial-map-controls{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin:12px 0;font-size:12px;color:var(--rd-muted)}
.rd-spatial-map-controls select{margin-left:6px;padding:8px;border:1px solid var(--rd-line);border-radius:4px;background:var(--rd-bg);color:var(--rd-ink);font:inherit;min-height:44px}
.rd-spatial-pitch{display:block;width:100%;max-width:760px;height:auto;margin:0 auto}
.rd-spatial-grass{fill:#143f36;stroke:#b4d4c5;stroke-width:.22}
.rd-spatial-lines{stroke:#9bbcaf;stroke-width:.22;opacity:.7}
.rd-spatial-dot--for{fill:#f8c75a;fill-opacity:.65;stroke:#402c00;stroke-width:.09}
.rd-spatial-dot--against{fill:#65c9f5;fill-opacity:.55;stroke:#082c49;stroke-width:.09}
.rd-spatial-dot--goal{fill-opacity:1;stroke:white;stroke-width:.18}
.rd-spatial-legend{display:flex;flex-wrap:wrap;gap:8px 18px;margin:12px 0 22px;font-size:12px;color:var(--rd-muted)}
.rd-spatial-legend-for::before,.rd-spatial-legend-against::before{content:"";display:inline-block;width:9px;height:9px;margin-right:6px;border-radius:50%;background:#e8ac24}
.rd-spatial-legend-against::before{background:#339ac7}
.rd-spatial-table-wrap{max-width:100%;min-width:0}
.rd-spatial-table{table-layout:fixed;width:100%;border-collapse:collapse;font-size:13px}
.rd-spatial-table caption{text-align:left;margin:0 0 12px;font-size:12px;color:var(--rd-muted)}
.rd-shell .rd-spatial-table th,.rd-shell .rd-spatial-table td{padding:12px 8px;text-align:left;vertical-align:top;border-bottom:1px solid var(--rd-line);white-space:normal;word-break:normal;overflow-wrap:anywhere}
.rd-spatial-table th:first-child{width:34%}
.rd-spatial-table th small,.rd-spatial-table td span{display:block;margin-top:4px;color:var(--rd-muted);font-size:11px;font-weight:400}
.rd-spatial-table td strong{font-weight:650}
.rd-spatial-focus{background:color-mix(in srgb,var(--rd-accent) 8%,transparent)}
.rd-spatial-limits{margin-top:18px;font-size:12px;color:var(--rd-muted);line-height:1.65}
.rd-spatial-limits summary{cursor:pointer;padding:10px 0;min-height:44px}
@media(max-width:480px){.rd-spatial-samples{grid-template-columns:1fr;gap:0}.rd-shell .rd-spatial-table th,.rd-shell .rd-spatial-table td{padding:10px 4px;font-size:12px}.rd-spatial-table td span{font-size:10px}.rd-spatial-directions button{flex:1;min-width:0;padding:10px}.rd-spatial-map-controls>span{font-size:11px}}
.rd-shell .rd-h2h-count{margin:0 0 12px;font-size:11px;color:var(--rd-muted)}
.rd-shell .rd-h2h-timeline{list-style:none;margin:0;padding:0 0 0 18px;border-left:1px solid var(--rd-line)}
.rd-shell .rd-h2h-timeline>li{position:relative;padding:0;margin:0}
.rd-shell .rd-h2h-timeline>li::before{content:"";position:absolute;left:-22px;top:22px;width:7px;height:7px;border:1px solid var(--rd-line);border-radius:50%;background:var(--rd-bg)}
.rd-shell .rd-h2h-timeline>li:first-child::before{background:var(--rd-accent);border-color:var(--rd-accent)}
.rd-shell .rd-h2h-meeting{margin:0;padding:0;border:0;border-bottom:1px solid var(--rd-line);border-radius:0;background:none;box-shadow:none;min-width:0}
.rd-shell .rd-h2h-meeting>summary{display:block;list-style:none;padding:12px 8px;cursor:pointer;min-width:0;color:var(--rd-ink);background:none}
.rd-shell .rd-h2h-meeting>summary::-webkit-details-marker{display:none}
.rd-shell .rd-h2h-meeting>summary::marker{content:""}
.rd-shell .rd-h2h-meeting>summary:focus-visible{outline:2px solid var(--rd-accent);outline-offset:2px}
.rd-shell .rd-h2h-meeting.is-latest>summary{background:color-mix(in srgb,var(--rd-accent) 5%,transparent)}
.rd-shell .rd-h2h-meta{display:flex;align-items:baseline;gap:8px;font-size:10px;line-height:1.4;color:var(--rd-muted);margin-bottom:7px}
.rd-h2h-meta>time{flex-shrink:0;font-variant-numeric:tabular-nums}
.rd-h2h-meta>span{flex:1;min-width:0;overflow-wrap:anywhere}
.rd-shell .rd-h2h-meta>small{font-size:9px;color:var(--rd-accent);white-space:nowrap}
.rd-h2h-toggle{width:12px;flex-shrink:0;font-style:normal;text-align:center;color:var(--rd-muted)}
.rd-h2h-toggle::before{content:"+"}.rd-h2h-meeting[open] .rd-h2h-toggle::before{content:"−"}
.rd-shell .rd-h2h-scoreline{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:16px}
.rd-shell .rd-h2h-scoreline>span{font-size:14px;font-weight:600;line-height:1.35;min-width:0;overflow-wrap:anywhere}
.rd-h2h-home{text-align:left}.rd-h2h-away{text-align:right}
.rd-shell .rd-h2h-scoreline>b{display:flex;align-items:center;gap:7px;font-size:24px;line-height:1.2;font-weight:750;font-variant-numeric:tabular-nums;white-space:nowrap}
.rd-h2h-scoreline>b>i{font-style:normal;font-size:14px;font-weight:400;color:var(--rd-muted)}
.rd-shell .rd-h2h-events{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:8px 8px 16px;margin:0;border:0;background:none}
.rd-shell .rd-h2h-events>section{min-width:0;margin:0;padding:0;border:0;background:none}
.rd-shell .rd-h2h-events h3{font:700 11px/1.4 Inter,system-ui,sans-serif;margin:0 0 8px;color:var(--rd-muted)}
.rd-shell .rd-h2h-events ul{list-style:none;margin:0;padding:0}
.rd-shell .rd-h2h-events li{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin:0;padding:5px 0;min-width:0}
.rd-shell .rd-h2h-events li>div{min-width:0;overflow-wrap:anywhere}
.rd-shell .rd-h2h-events li strong{display:block;font-size:12px;font-weight:600;line-height:1.4;color:var(--rd-ink)}
.rd-shell .rd-h2h-events li small{display:block;font-size:10px;line-height:1.5;color:var(--rd-muted)}
.rd-shell .rd-h2h-events li time{flex-shrink:0;font-size:11px;font-variant-numeric:tabular-nums;color:var(--rd-ink)}
.rd-shell .rd-h2h-empty{font-size:11px;line-height:1.5;margin:0;color:var(--rd-muted)}
@media(max-width:600px){.rd-shell .rd-h2h-timeline{padding-left:12px}.rd-shell .rd-h2h-timeline>li::before{left:-16px}.rd-shell .rd-h2h-meeting>summary{padding:11px 4px}.rd-shell .rd-h2h-meta{font-size:9px;gap:5px}.rd-shell .rd-h2h-meta>small{font-size:8px}.rd-shell .rd-h2h-scoreline{gap:8px}.rd-shell .rd-h2h-scoreline>span{font-size:12px}.rd-shell .rd-h2h-scoreline>b{font-size:20px;gap:4px}.rd-shell .rd-h2h-events{grid-template-columns:1fr;gap:16px;padding:8px 4px 14px}}
.rd-shell .rd-tactical-comparison{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:28px;row-gap:12px;margin:0 0 24px}
.rd-shell .rd-tactical-column{display:grid;grid-template-rows:subgrid;grid-row:1 / span 4;min-width:0;background:none;border:0;padding:0}
.rd-shell .rd-tactical-team>span{display:block;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--rd-home);margin-bottom:5px}
.rd-shell [data-tactical-side="away"] .rd-tactical-team>span{color:var(--rd-away)}
.rd-shell .rd-tactical-team h3{margin:0;font:700 18px/1.3 Inter,system-ui,sans-serif;letter-spacing:-.025em;overflow-wrap:anywhere;color:var(--rd-ink)}
.rd-shell .rd-tactical-column .rd-tactical-baseline{margin:0;font-size:11px;line-height:1.5;overflow-wrap:anywhere}
.rd-shell .rd-tactical-column .rd-tactical-metrics{display:grid;grid-template-columns:1fr;gap:0;margin:0}
.rd-shell .rd-tactical-metrics>div{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:7px 0;border-bottom:1px solid var(--rd-line);min-width:0}
.rd-shell .rd-tactical-metrics dt{font-size:11px;font-weight:400;color:var(--rd-muted);text-transform:none;letter-spacing:0}
.rd-shell .rd-tactical-metrics dd{margin:0;font-size:16px;font-weight:650;color:var(--rd-ink);font-variant-numeric:tabular-nums}
.rd-shell .rd-tactical-directions{min-width:0}
.rd-shell .rd-tactical-directions .rd-empty{margin:0;padding:0;border:0;font-size:11px;line-height:1.5}
.rd-shell .rd-tactical-directions .rd-channels{margin:4px 0 10px;gap:12px}
.rd-shell .rd-tactical-directions .rd-channels>div{grid-template-columns:52px minmax(0,1fr) 46px;gap:8px;font-size:11px}
.rd-shell .rd-tactical-directions>.rd-footnote{margin:6px 0 0;font-size:10px;line-height:1.5}
@media(max-width:600px){.rd-shell .rd-tactical-comparison{column-gap:14px;row-gap:10px}.rd-shell .rd-tactical-team h3{font-size:14px}.rd-shell .rd-tactical-column .rd-tactical-baseline{font-size:9px}.rd-shell .rd-tactical-metrics dt{font-size:10px}.rd-shell .rd-tactical-metrics dd{font-size:14px}.rd-shell .rd-tactical-directions .rd-channels>div{grid-template-columns:minmax(0,1fr) auto;gap:4px;font-size:10px}.rd-shell .rd-tactical-directions .rd-channels i{grid-column:1 / -1;grid-row:2;height:5px}.rd-shell .rd-tactical-directions .rd-channels strong{grid-column:2;grid-row:1}.rd-shell .rd-tactical-directions .rd-footnote{font-size:9px;line-height:1.5}}
.rd-shell .rd-referee-history{max-width:720px;margin:20px 0 8px;padding-top:16px;border-top:1px solid var(--rd-line);color:var(--rd-ink)}
