body[data-reading-detail-theme="champions"] .rd-shell .rd-back a{padding:0;border:0;border-radius:0;background:none;box-shadow:none;font-size:12px;text-transform:none;letter-spacing:normal}
/* Champions validation labels remain distinct from the forecast name. */
