@media(max-width:767px){.rd-shell .rd-diverging-top b{font-size:16px}}

.rd-shell .rd-recent-form>h3{font-family:Inter,system-ui,sans-serif;font-size:10px;line-height:1.35;font-weight:900;text-transform:uppercase;letter-spacing:.16em;color:#967126}@media(max-width:767px){.rd-shell .rd-recent-form>h3{font-size:9px}}

@media(max-width:767px){.rd-shell .rd-match-meta>span:nth-of-type(2){flex-basis:100%;text-align:left;justify-self:start}.rd-shell .rd-match-meta>span:nth-of-type(2)::before{content:none}}

@media(max-width:767px){
