/* Mobile navigation: compact brand and almost full-height menu. */
@media(max-width:760px){
 .site-header{align-items:center}
 .site-header>.brand{position:static}
 .site-header>.brand>span:last-child{display:block;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);max-width:calc(100% - 128px);text-align:center}
 .site-header>.brand small{display:none}
 .site-header>.menu-button{display:grid;place-content:center;gap:5px;width:44px;height:44px;padding:10px;font-size:0;flex-shrink:0}
 .site-header>.menu-button::before,.site-header>.menu-button::after{content:"";display:block;width:20px;height:2px;background:currentColor;transition:transform .18s ease}
 .site-header>.menu-button::before{box-shadow:0 6px currentColor;transform:translateY(-3px)}
 .site-header>.menu-button::after{transform:translateY(2px)}
 .site-header>.menu-button[aria-expanded="true"]::before{box-shadow:none;transform:translateY(3.5px) rotate(45deg)}
 .site-header>.menu-button[aria-expanded="true"]::after{transform:translateY(-3.5px) rotate(-45deg)}
}
@media(prefers-reduced-motion:reduce){.site-header>.menu-button::before,.site-header>.menu-button::after{transition:none}}

@media(max-width:760px){
