 .site-header>.menu-button::after{opacity:0;transform:none}
 .site-header>.menu-button[aria-expanded="true"]::before{transform:rotate(45deg);box-shadow:none}
 .site-header>.menu-button[aria-expanded="true"]::after{opacity:1;transform:rotate(-45deg)}
}

