#team-squad-app.team-dashboard-pilot .roster-sort:focus-visible{outline:2px solid #9a8046;outline-offset:4px}
#team-squad-app.team-dashboard-pilot .roster-sort:hover{color:#8b7038}

/* Short inset accents, matching the approved roster render. */
#team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th[colspan]{border-bottom:0;background-image:linear-gradient(#b69857,#b69857);background-repeat:no-repeat;background-position:center bottom;background-size:calc(100% - 32px) 2px}
#team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th[colspan]:nth-child(n+4){background-image:linear-gradient(#a8ddeb,#a8ddeb)}

/* Warm brown tint on the roster group headings. */
#team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th{background-color:#c5bdb6}
#team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th:first-child{background-color:#c5bdb6}
#team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:nth-child(2)>th{background-color:#c5bdb6}

/* Alternating visible rows follow the current sorting and filtering. */
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:nth-child(odd)>td{background-color:#fff}
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:nth-child(even)>td{background-color:#f3f4f4}
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:is(:hover,:focus-within)>td{background-color:#eaecea}

/* Slightly denser roster rows while keeping name and role readable. */
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody td{padding-block:10px}
#team-squad-app.team-dashboard-pilot .squad-table--compact .player-label{gap:3px}

/* Brush headings share the roster header's warm taupe. */
body #team-squad-app.team-dashboard-pilot .squad-leader-card:nth-child(n) header::before{background:#c5bdb6}
#team-squad-app.team-dashboard-pilot .squad-leader-card header,#team-squad-app.team-dashboard-pilot .squad-leader-card header h4,#team-squad-app.team-dashboard-pilot .squad-leader-card header>span{color:#243a3b}

/* Layered translucent pigment and feathered edges for a watercolor wash. */
body #team-squad-app.team-dashboard-pilot .squad-leader-card:nth-child(n) header::before{
 background:radial-gradient(ellipse at 18% 65%,rgba(160,145,132,.32),transparent 52%),radial-gradient(ellipse at 72% 30%,rgba(224,216,206,.65),transparent 48%),radial-gradient(ellipse at 85% 80%,rgba(166,150,136,.28),transparent 42%),linear-gradient(102deg,rgba(197,189,182,.22),rgba(197,189,182,.78) 19%,rgba(187,175,164,.58) 48%,rgba(197,189,182,.72) 76%,rgba(197,189,182,.16));
 filter:blur(1.2px);
 mask-image:linear-gradient(90deg,transparent,#000 6%,#000 93%,transparent),linear-gradient(0deg,transparent,#000 18%,#000 78%,transparent);
 mask-composite:intersect;
 -webkit-mask-image:linear-gradient(90deg,transparent,#000 6%,#000 93%,transparent),linear-gradient(0deg,transparent,#000 18%,#000 78%,transparent);
 -webkit-mask-composite:source-in;
}
body #team-squad-app.team-dashboard-pilot .squad-leader-card:nth-child(even) header::before{background-position:12px -3px,-18px 4px,8px 0,0 0;filter:blur(1.5px)}

/* Clear type hierarchy in the team season statistics. */
#team-squad-app.team-dashboard-pilot .team-statistics-groups thead th{color:#000;font-weight:700!important}
#team-squad-app.team-dashboard-pilot .team-statistics-groups tbody :is(th,td){font-size:11px;line-height:1.45}
#team-squad-app.team-dashboard-pilot .team-statistics-groups thead th{font-size:12px}

/* One consistent separator for every team-statistics row. */
#team-squad-app.team-dashboard-pilot .team-statistics-groups table{border-collapse:collapse;border-spacing:0;border:0}
#team-squad-app.team-dashboard-pilot .team-statistics-groups :is(thead,tbody,tr){border:0;box-shadow:none}
#team-squad-app.team-dashboard-pilot .team-statistics-groups :is(th,td){border:0;border-bottom:1px solid #d5dcdf;box-shadow:none}

/* Slightly stronger separator beneath the statistics column headings. */
#team-squad-app.team-dashboard-pilot .team-statistics-groups thead th{border-bottom-color:#adb8bc}

/* Clean leaderboard headings without decorative brush strokes. */
body #team-squad-app.team-dashboard-pilot .squad-leader-card:nth-child(n) header::before{content:none;display:none}

/* Stronger divider between leaderboard titles and player data. */
#team-squad-app.team-dashboard-pilot .squad-leader-card header{border-bottom:1px solid #697b7d}

/* Mobile objective: three clearly separated blocks with a shared left edge. */
@media(max-width:700px){
 #team-squad-app.team-dashboard-pilot .team-season-objective{display:flex;flex-direction:column;gap:0;width:100%}
 #team-squad-app.team-dashboard-pilot .team-season-objective>.team-season-target{width:100%;padding-bottom:20px}
 #team-squad-app.team-dashboard-pilot .team-season-objective>.team-season-indicators{display:flex;flex-direction:column;gap:0;width:100%}
 #team-squad-app.team-dashboard-pilot .team-season-indicators>div{width:100%;padding:18px 0;border-top:1px solid #d5dcdf;text-align:left;box-sizing:border-box}
 #team-squad-app.team-dashboard-pilot .team-season-objective .team-summary-label{font-size:12px;line-height:1.5;color:#43595b}
 #team-squad-app.team-dashboard-pilot .team-season-objective p{font-size:12px;line-height:1.6;max-width:42ch;margin-top:6px}
 #team-squad-app.team-dashboard-pilot .team-season-target h3{font-size:20px;margin:6px 0 10px}
 #team-squad-app.team-dashboard-pilot .team-indicator-value{font-size:28px;margin:6px 0 10px}
 #team-squad-app.team-dashboard-pilot .team-season-indicators progress{height:7px;margin:12px 0}
}

/* Center the stacked team-statistics tables on mobile. */
@media(max-width:760px){
 #team-squad-app.team-dashboard-pilot .team-statistics-groups{justify-items:center}
 #team-squad-app.team-dashboard-pilot .team-statistics-groups>section{width:100%;max-width:340px;margin-inline:auto}
 #team-squad-app.team-dashboard-pilot .team-statistics-groups h3{text-align:center}
 #team-squad-app.team-dashboard-pilot .team-statistics-groups table{width:100%;max-width:none;margin-inline:auto}
}

/* Center the individual leaderboards alongside the mobile team statistics. */
@media(max-width:760px){
 #team-squad-app.team-dashboard-pilot .team-leaders-compact .squad-leader-grid{grid-template-columns:minmax(0,340px);justify-content:center;justify-items:stretch;gap:24px}
 #team-squad-app.team-dashboard-pilot .squad-leader-card{width:100%;min-width:0;margin-inline:auto}
}

/* Compact touch-friendly roster viewport: more statistics beside the pinned name. */
@media(max-width:760px){
 body #team-squad-app.team-dashboard-pilot .squad-table--compact{min-width:1270px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .squad-col-player{width:140px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact :is(.squad-col-played,.squad-col-minutes){width:62px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .squad-col-stat{width:72px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody td:first-child,
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th:first-child{width:140px;min-width:140px;max-width:140px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact :is(th,td){padding-inline:8px;font-size:12px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .player-label{font-size:12px;line-height:1.4;overflow-wrap:anywhere}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .roster-player-role{font-size:10px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th[colspan]{font-size:10px;letter-spacing:0;white-space:nowrap}
 #team-squad-app.team-dashboard-pilot .team-full-roster-section .squad-table-wrap{max-height:65svh;overflow:auto;overscroll-behavior-x:contain;overscroll-behavior-y:auto;-webkit-overflow-scrolling:touch;scrollbar-gutter:stable}
 #team-squad-app.team-dashboard-pilot .roster-scroll-hint{font-size:11px;line-height:1.5}
}

/* Seal mobile sticky seams with opaque row colors and whole-pixel geometry. */
@media(max-width:760px){
 body #team-squad-app.team-dashboard-pilot .squad-table--compact{border-collapse:separate;border-spacing:0;background:#fff}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr{--roster-row-bg:#fff}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:nth-child(even){--roster-row-bg:#f3f4f4}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:is(:hover,:focus-within){--roster-row-bg:#eaecea}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr>td{background:var(--roster-row-bg);background-clip:border-box;border:0;border-bottom:1px solid #dce2e3;box-sizing:border-box;height:56px;line-height:18px;box-shadow:none}
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr>td:first-child{box-shadow:1px 0 0 var(--roster-row-bg),2px 0 0 var(--roster-row-bg)}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .player-label{line-height:18px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact .roster-player-role{line-height:14px}
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead th{background-color:#c5bdb6;background-clip:border-box;border-inline:0;box-shadow:0 1px 0 #c5bdb6}
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th:first-child{box-shadow:1px 0 0 #c5bdb6,2px 0 0 #c5bdb6,0 1px 0 #c5bdb6}
}

/* Continuous row separators: sticky-cell shadows must not cover their borders. */
@media(max-width:760px){
 #team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr>td:first-child{box-shadow:none}
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead th{box-shadow:none;border-bottom:0}
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:first-child>th:first-child,
 #team-squad-app.team-dashboard-pilot .squad-table--compact thead tr:nth-child(2)>th{box-shadow:none;border-bottom:1px solid #dce2e3}
}

/* Individual leaderboards are static: no lift, hover tint or name underline. */
#team-squad-app.team-dashboard-pilot .squad-leader-card{transition:none}
#team-squad-app.team-dashboard-pilot .squad-leader-card:hover{transform:none;border-color:var(--line)}
#team-squad-app.team-dashboard-pilot .squad-leader-card .leader-player,
#team-squad-app.team-dashboard-pilot .squad-leader-card .leader-player:is(:hover,:focus-visible){color:var(--text);text-decoration:none;cursor:default;transition:none}

/* Preserve roster row hover independently of the static leaderboard cards. */
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:is(:hover,:focus-within)>td{background-color:#eaecea}
#team-squad-app.team-dashboard-pilot .squad-table--compact tbody tr:is(:hover,:focus-within)>td:first-child{background-color:#d5f1f2}

@media(min-width:761px) and (max-width:1024px){body[data-page="team-stats"] #app>.team-directory-grid .team-flip-card{height:auto}.team-flip-inner{min-height:176px;padding:16px;gap:12px}.team-flip-back{gap:6px}}

css/tokens.css:
/* Foundations only. Theme tokens do not restyle existing components.
   Legacy colour/radius/shadow families retain their current cascade until migration. */
:root{
  --ds-font-body:"Inter","Segoe UI",Arial,sans-serif;
  --ds-font-display:"Newsreader",Georgia,serif;
  --ds-font-data:var(--ds-font-body);
  --ds-text-meta:12px;
  --ds-text-compact:14px;
  --ds-text-body:16px;
  --ds-title-page:clamp(40px,4vw,48px);
  --ds-title-hero:clamp(40px,6vw,76px);
  --ds-title-section:clamp(24px,3vw,32px);
  --ds-title-subsection:20px;
  --ds-leading-body:1.55;
  --ds-leading-title:1.15;
  --ds-space-1:4px;
  --ds-space-2:8px;
  --ds-space-3:12px;
  --ds-space-4:16px;
  --ds-space-5:24px;
  --ds-space-6:32px;
  --ds-space-7:48px;
  --ds-space-8:64px;
  --ds-content-max:1050px;
  --ds-page-gutter:24px;
  --ds-radius-control:8px;
  --ds-radius-card:16px;
  --ds-radius-panel:24px;
  --ds-radius-pill:999px;
  --ds-border-width:1px;
  --ds-control-min-height:44px;
  --ds-control-font-size:14px;
  --ds-control-padding-block:10px;
  --ds-control-padding-inline:16px;
  --ds-glass-blur:blur(22px) saturate(135%);
  --ds-transition-fast:.18s ease;
  --ds-transition-base:.28s cubic-bezier(.22,.8,.22,1);

  --ds-color-page:#F8F7F4;
  --ds-color-surface:#FFFFFF;
  --ds-color-surface-soft:#EEF4F6;
  --ds-color-text:#283A3B;
  --ds-color-text-muted:#52666D;
  --ds-color-border:#D6E1E5;
  --ds-color-accent:#1E5F9D;
  --ds-color-accent-strong:#164C82;
  --ds-color-on-accent:#FFFFFF;
  --ds-color-focus:#1E5F9D;
  --ds-color-glass:rgba(220,233,236,.78);
  --ds-color-glass-border:rgba(255,255,255,.68);
  --ds-shadow-card:0 8px 24px rgba(20,43,59,.09),inset 0 1px rgba(255,255,255,.2);
  --ds-shadow-floating:0 20px 48px rgba(20,43,59,.16);
  --ds-page-background:
    radial-gradient(ellipse 85vw 90vh at 105% 8%,rgba(234,243,245,.78),transparent 78%),
    radial-gradient(ellipse 78vw 85vh at -12% 68%,rgba(245,241,235,.72),transparent 80%),
    radial-gradient(ellipse 70vw 80vh at 70% 112%,rgba(233,236,235,.48),transparent 82%),
    radial-gradient(ellipse 65vw 75vh at 30% -18%,rgba(255,255,255,.85),transparent 82%);
}
/* Body-local values follow the existing competition and first-paint reading hooks. */
body[data-page="champions"],body[data-reading-detail-theme="champions"],body[data-competition-theme="champions"]{
  --ds-color-page:#07152C;
  --ds-color-surface:#10233F;
  --ds-color-surface-soft:#142D4D;
  --ds-color-text:#F2F6FF;
  --ds-color-text-muted:#AFC3DC;
  --ds-color-border:#304762;
  --ds-color-accent:#71B8FF;
  --ds-color-accent-strong:#0D55CB;
  --ds-color-focus:#9EDBFF;
  --ds-color-glass:rgba(16,35,63,.86);
  --ds-color-glass-border:rgba(147,200,255,.24);
  --ds-shadow-card:0 8px 24px rgba(0,7,28,.2),inset 0 1px rgba(255,255,255,.08);
  --ds-shadow-floating:0 20px 48px rgba(0,7,28,.38);
  --ds-page-background:
    radial-gradient(ellipse at 70% -10%,#153964 0,transparent 45rem),
    radial-gradient(ellipse at 0% 55%,#102747 0,transparent 40rem);
}
@media(max-width:600px){:root{--ds-page-gutter:16px}}
